for (const m of MINERALS) nodeMats[m] = new THREE.MeshStandardMaterial({
  // bright enough to cross the bloom threshold: a seam should read as a light
  // source on the far side of the worldlet, not as a coloured pebble
  color: MIN_COL[m], emissive: MIN_COL[m], emissiveIntensity: 1.35,
  roughness: 0.25, flatShading: true });
const nodeMat = nodeMats[CRYSTAL];
// A SEAM IS A CLUSTER. One floating diamond per tile read as a placeholder
// token; three crystals of different sizes leaning out of the ground read as
// something growing there. Merged, so it is still one draw call per seam.
// Three clusters, not one rotated four ways: with a dozen seams on a face the
// repeat is obvious the moment two of them are in frame together. Different
// counts and different leans, so they differ in silhouette and not only in
// orientation.
const nodeGeos = [
  mergeParts([
    { g: new THREE.OctahedronGeometry(0.58, 0) },
    { g: new THREE.OctahedronGeometry(0.30, 0), x: 0.44, y: -0.22, z: 0.20,
      rz: 0.5, ry: 0.8 },
    { g: new THREE.OctahedronGeometry(0.23, 0), x: -0.38, y: -0.26, z: -0.30,
      rz: -0.6, ry: 0.3 },
  ]),
  mergeParts([
    { g: new THREE.OctahedronGeometry(0.44, 0), rz: 0.34 },
    { g: new THREE.OctahedronGeometry(0.40, 0), x: -0.30, y: -0.10, z: 0.34,
      rz: -0.42, ry: 1.1 },
    { g: new THREE.OctahedronGeometry(0.26, 0), x: 0.36, y: -0.20, z: -0.24,
      rz: 0.7 },
    { g: new THREE.OctahedronGeometry(0.17, 0), x: 0.10, y: -0.30, z: 0.44 },
  ]),
  mergeParts([
    { g: new THREE.OctahedronGeometry(0.66, 0), rz: -0.22, ry: 0.4 },
    { g: new THREE.OctahedronGeometry(0.20, 0), x: 0.46, y: -0.30, z: -0.10,
      rz: 0.9 },
  ]),
];
const nodeGeo = nodeGeos[0];      // the shape a thumbnail or a fallback uses
let rngState = 1337;
const rnd = () => (rngState = (rngState * 1664525 + 1013904223) % 4294967296) / 4294967296;
const NODE_COUNT = Math.max(6, Math.min(40, Math.round(N * N * 0.028)));
for (let k = 0; k < NODE_COUNT; k++) {
  const f = Math.floor(rnd() * 6);
  const i = 2 + Math.floor(rnd() * (N - 4));
  const j = 2 + Math.floor(rnd() * (N - 4));
  const c = cells[f][i][j];
  if (c.t !== EMPTY) continue;
  c.t = NODE;
  c.min = MINERAL_OF_FACE[f];
  const m = new THREE.Mesh(nodeGeos[Math.floor(rnd() * nodeGeos.length)],
                           nodeMats[c.min]);
  seat(m, f, i, j, Math.floor(rnd() * 4), 0.66 + rnd() * 0.12);
  m.scale.setScalar(0.82 + rnd() * 0.42);
  m.userData.base = m.scale.x;      // the pulse scales relative to this
  m.userData.fsTag = { type: 'ore', name: MINERAL_NAME[c.min] + ' seam',
                       detail: FACES[f].name + ' face · tile ' + i + ',' + j,
                       face: f, i, j,
                       get rich() { return Math.round(c.rich * 100) + '%'; } };
  m.castShadow = true;
  m.userData.spin = 0.4 + rnd() * 0.6;
  m.userData.axis = FACES[f].n;      // spin about the face's up, not the world's
  scene.add(m);
  c.mesh = m;
}

// ── the tread, drawn rather than loaded ────────────────────────────────────
// A conveyor that does not visibly move is a green plank. Slats and chevrons
// on a 64px canvas, scrolled by the tick clock: one shared material animates
// every belt on the worldlet, and the direction reads without an arrow
// hovering over each tile.
function treadTexture() {
  const c = document.createElement('canvas');
  c.width = 64; c.height = 64;
  const g = c.getContext('2d');
  g.fillStyle = '#16362e'; g.fillRect(0, 0, 64, 64);
  g.fillStyle = '#1f4f43';
  for (let x = 0; x < 64; x += 16) g.fillRect(x, 0, 10, 64);   // slats across
  g.strokeStyle = '#57e0b0'; g.lineWidth = 4; g.lineCap = 'round';
  g.lineJoin = 'round';
  for (let x = 4; x < 64; x += 16) {                            // chevrons -> +u
    g.beginPath();
    g.moveTo(x, 18); g.lineTo(x + 8, 32); g.lineTo(x, 46);
    g.stroke();
  }
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  return t;
}
const TREAD = treadTexture();

// Scattered after the seams, so nothing lands on one: an ore seam is the only
// thing on the ground a player is looking FOR.
for (let k = 0; k < 320; k++) {
  const f = Math.floor(rnd() * 6);
  const i = 1 + Math.floor(rnd() * (N - 2));
  const j = 1 + Math.floor(rnd() * (N - 2));
  if (cells[f][i][j].t !== EMPTY) continue;
  scatterSpots.push({ f, i, j, kind: rnd() < 0.45 ? 0 : 1,
                      d: Math.floor(rnd() * 4), s: 0.75 + rnd() * 0.6 });
}

// ── build meshes ───────────────────────────────────────────────────────────
const MAT = {
  // EVERY MACHINE IS A LITTLE BIT ON. A dark object in a dark scene has no
  // silhouette; a faint self-lit trim gives each one an edge the bloom can
  // catch, which is most of why a lit game looks lit.
  miner: new THREE.MeshStandardMaterial({ color: 0xff5d73, roughness: 0.4,
    metalness: 0.35, emissive: 0x4a0d1a, emissiveIntensity: 0.9 }),
  belt: new THREE.MeshStandardMaterial({ color: 0x3ad39a, roughness: 0.6, metalness: 0.2 }),
  beltFrame: new THREE.MeshStandardMaterial({ color: 0x2b7f68, roughness: 0.45,
    metalness: 0.6, flatShading: true, emissive: 0x07271f,
    emissiveIntensity: 0.9 }),
  beltDeck: new THREE.MeshStandardMaterial({ map: TREAD, roughness: 0.85,
    metalness: 0.05 }),
  hub: new THREE.MeshStandardMaterial({ color: 0xffc75a, roughness: 0.35,
    metalness: 0.45, emissive: 0x6a4708, emissiveIntensity: 0.9,
    emissive: 0x6b4a00, emissiveIntensity: 0.6 }),
  forge: new THREE.MeshStandardMaterial({ color: 0xd94fb0, roughness: 0.34,
    metalness: 0.55, flatShading: true, emissive: 0x5c0f45,
    emissiveIntensity: 1.0 }),
  filt: new THREE.MeshStandardMaterial({ color: 0x2f8f7d, roughness: 0.55,
    metalness: 0.25, emissive: 0x0a3329, emissiveIntensity: 0.9 }),
  rift: new THREE.MeshStandardMaterial({ color: 0x6a3cff, emissive: 0x3a1c9c,
    emissiveIntensity: 0.8, roughness: 0.3, metalness: 0.5, flatShading: true }),
  smelt: new THREE.MeshStandardMaterial({ color: 0x8c6bff, roughness: 0.42,
    metalness: 0.4, emissive: 0x2a1b6a, emissiveIntensity: 0.85,
    emissive: 0x2a1470, emissiveIntensity: 0.5 }),
  split: new THREE.MeshStandardMaterial({ color: 0x4bb5ff, roughness: 0.45,
    metalness: 0.35, emissive: 0x0d3a63, emissiveIntensity: 0.9,
    emissive: 0x0d3f66, emissiveIntensity: 0.45 }),
};
// Each machine is authored as parts and merged into one geometry. Local +X is
// the heading and local +Y is up off the face, which is what seat() promises.
const _box = (w, h, d) => new THREE.BoxGeometry(w, h, d);
const _cyl = (rt, rb, h, n) => new THREE.CylinderGeometry(rt, rb, h, n);

// A quarter-turn deck. Ring sectors live in the XY plane, so laying one flat
// with rx=-90 maps ring (cos t, sin t) to local (cos t, 0, -sin t); every angle
// below was derived through that mapping, which is why they look off by a
// quarter turn if you read them as world angles.
function arcDeck(inner, outer, thetaStart, flip) {
  const g = new THREE.RingGeometry(inner, outer, 14, 1, thetaStart, Math.PI / 2);
  const pos = g.attributes.position, uv = g.attributes.uv;
  const mid = (inner + outer) / 2;
  // the arc is shorter than a tile, so the chevrons have to be packed to match
  // or the tread visibly changes speed through every corner
  const arcU = (Math.PI / 2) * mid / T;
  for (let k = 0; k < pos.count; k++) {
    const x = pos.getX(k), y = pos.getY(k);
    let th = Math.atan2(y, x);
    while (th < thetaStart - 1e-6) th += Math.PI * 2;
    const t = (th - thetaStart) / (Math.PI / 2);
    const r = Math.hypot(x, y);
    uv.setXY(k, (flip ? 1 - t : t) * arcU, (r - inner) / (outer - inner));
  }
  uv.needsUpdate = true;
  return g;
}
const ARC_R = T * 0.5, ARC_W = T * 0.30;

const GEO = {
  // A CONVEYOR, not a plank: side rails, an end roller at each end, a base
  // plate, and a separate deck that carries the moving tread.
  beltFrame: mergeParts([
    { g: _box(T * 0.96, 0.05, T * 0.82), y: 0.03 },
    { g: _box(T * 0.96, 0.14, 0.09), y: 0.15, z: T * 0.37 },
    { g: _box(T * 0.96, 0.14, 0.09), y: 0.15, z: -T * 0.37 },
    { g: _cyl(0.105, 0.105, T * 0.70, 8), y: 0.13, x: T * 0.41, rx: Math.PI / 2 },
    { g: _cyl(0.105, 0.105, T * 0.70, 8), y: 0.13, x: -T * 0.41, rx: Math.PI / 2 },
  ]),
  beltDeck: _box(T * 0.86, 0.06, T * 0.60),

  // A: enters across the +Z edge heading -Z, leaves out the +X edge.
  // B: enters across the -Z edge heading +Z, leaves out the +X edge.
  beltDeckA: mergeParts([{ g: arcDeck(ARC_R - ARC_W, ARC_R + ARC_W, Math.PI / 2, true),
                           rx: -Math.PI / 2, x: T / 2, z: T / 2, y: 0.155 }]),
  beltDeckB: mergeParts([{ g: arcDeck(ARC_R - ARC_W, ARC_R + ARC_W, Math.PI, false),
                           rx: -Math.PI / 2, x: T / 2, z: -T / 2, y: 0.155 }]),
  beltFrameA: mergeParts([
    { g: new THREE.RingGeometry(ARC_R - ARC_W - 0.11, ARC_R + ARC_W + 0.11, 14, 1,
                                Math.PI / 2, Math.PI / 2),
      rx: -Math.PI / 2, x: T / 2, z: T / 2, y: 0.03 },
    { g: _cyl(0.105, 0.105, T * 0.70, 8), y: 0.13, x: T * 0.41, rx: Math.PI / 2 },
    { g: _cyl(0.105, 0.105, T * 0.70, 8), y: 0.13, z: T * 0.41,
      rx: Math.PI / 2, ry: Math.PI / 2 },
  ]),
  // A MERGE. Straight run with a ramp on each flank: it does not try to say
  // WHICH side is feeding — with two or three inputs there is no single answer
  // and a piece that guessed would be wrong more often than not — it says that
  // this is where lines join, which is the thing worth seeing from a distance.
  beltFrameJ: mergeParts([
    { g: _box(T * 0.96, 0.05, T * 0.94), y: 0.03 },
    { g: _box(T * 0.96, 0.14, 0.09), y: 0.15, z: T * 0.37, tint: 0.85 },
    { g: _box(T * 0.96, 0.14, 0.09), y: 0.15, z: -T * 0.37, tint: 0.85 },
    { g: _cyl(0.105, 0.105, T * 0.70, 8), y: 0.13, x: T * 0.41, rx: Math.PI / 2 },
    { g: _cyl(0.105, 0.105, T * 0.70, 8), y: 0.13, x: -T * 0.41, rx: Math.PI / 2 },
    { g: _box(T * 0.34, 0.05, T * 0.30), y: 0.13, z: T * 0.44, rx: 0.32, tint: 0.7 },
    { g: _box(T * 0.34, 0.05, T * 0.30), y: 0.13, z: -T * 0.44, rx: -0.32, tint: 0.7 },
  ]),
  beltFrameB: mergeParts([
    { g: new THREE.RingGeometry(ARC_R - ARC_W - 0.11, ARC_R + ARC_W + 0.11, 14, 1,
                                Math.PI, Math.PI / 2),
      rx: -Math.PI / 2, x: T / 2, z: -T / 2, y: 0.03 },
    { g: _cyl(0.105, 0.105, T * 0.70, 8), y: 0.13, x: T * 0.41, rx: Math.PI / 2 },
    { g: _cyl(0.105, 0.105, T * 0.70, 8), y: 0.13, z: -T * 0.41,
      rx: Math.PI / 2, ry: Math.PI / 2 },
  ]),

  // a rig with legs, cross-braces, a motor over the shaft it drives, and a
  // control box on one side, so a miner reads as MINING rather than as a table
  miner: mergeParts([
    { g: _box(T * 0.86, 0.14, T * 0.86), y: 0.07, tint: 0.6 },   // skirt
    { g: _box(T * 0.74, 0.24, T * 0.74), y: 0.24 },              // deck
    { g: _box(0.13, 0.95, 0.13), y: 0.68, x: T * 0.28, z: T * 0.28 },
    { g: _box(0.13, 0.95, 0.13), y: 0.68, x: -T * 0.28, z: T * 0.28 },
    { g: _box(0.13, 0.95, 0.13), y: 0.68, x: T * 0.28, z: -T * 0.28 },
    { g: _box(0.13, 0.95, 0.13), y: 0.68, x: -T * 0.28, z: -T * 0.28 },
    { g: _box(T * 0.62, 0.07, 0.09), y: 0.66, z: T * 0.28, rz: 0.55 },  // braces
    { g: _box(T * 0.62, 0.07, 0.09), y: 0.66, z: -T * 0.28, rz: -0.55 },
    { g: _box(T * 0.70, 0.13, T * 0.70), y: 1.18 },              // head plate
    { g: _cyl(0.10, 0.10, 0.86, 6), y: 0.74 },                   // shaft
    { g: _cyl(0.19, 0.19, 0.30, 8), y: 1.38, rz: Math.PI / 2, tint: 0.72 }, // motor
    { g: _box(0.20, 0.30, 0.24), y: 0.52, x: T * 0.36, tint: 0.62 }, // control box
  ]),
  minerBit: _cyl(0.02, 0.28, 0.5, 6),

  arrow: new THREE.ConeGeometry(0.2, 0.5, 4),

  // a landing pad with ribs, a collar and a mast: the place everything is
  // going to should look like a destination, not another box
  hub: mergeParts((() => {
    const parts = [
      { g: _cyl(T * 0.66, T * 0.70, 0.10, 12), y: 0.05, tint: 0.6 }, // skirt
      { g: _cyl(T * 0.54, T * 0.62, 0.26, 12), y: 0.20 },          // pad
      { g: new THREE.TorusGeometry(T * 0.46, 0.06, 6, 18), y: 0.36, rx: Math.PI / 2 },
      { g: _cyl(0.09, 0.09, 0.85, 6), y: 0.78 },                   // mast
      { g: _cyl(0.16, 0.16, 0.10, 8), y: 1.06 },                   // collar
    ];
    // radiating ribs, so the pad has a direction to it under the landing ring
    for (let k = 0; k < 6; k++) {
      const a = (k / 6) * Math.PI * 2;
      parts.push({ g: _box(T * 0.30, 0.07, 0.10), y: 0.35,
                   x: Math.cos(a) * T * 0.30, z: Math.sin(a) * T * 0.30, ry: -a });
    }
    return parts;
  })()),

  // a furnace with a door facing its output, vents facing away, and a flue.
  // Detail that explains the machine reads as design; detail scattered for
  // texture's sake reads as noise.
  smelt: mergeParts([
    { g: _box(T * 0.90, 0.13, T * 0.90), y: 0.065, tint: 0.6 },  // skirt
    { g: _box(T * 0.78, 0.92, T * 0.78), y: 0.58 },              // body
    { g: _box(T * 0.90, 0.11, T * 0.90), y: 1.09 },              // cap
    { g: _box(T * 0.42, 0.46, 0.10), y: 0.50, x: T * 0.40, tint: 0.72 }, // frame
    { g: _box(T * 0.30, 0.34, 0.07), y: 0.50, x: T * 0.44, tint: 0.34 }, // door
    { g: _box(0.09, 0.09, T * 0.50), y: 0.86, z: -T * 0.40, tint: 0.5 }, // vents
    { g: _box(0.09, 0.09, T * 0.50), y: 0.70, z: -T * 0.40, tint: 0.5 },
    { g: _box(0.09, 0.09, T * 0.50), y: 0.54, z: -T * 0.40, tint: 0.5 },
    { g: _cyl(0.13, 0.17, 0.62, 6), y: 1.42, x: T * 0.22, z: -T * 0.22 },
    { g: new THREE.TorusGeometry(0.16, 0.035, 5, 10), y: 1.62,
      x: T * 0.22, z: -T * 0.22, rx: Math.PI / 2 },              // flue lip
  ]),

  split: mergeParts([
    { g: _cyl(T * 0.50, T * 0.50, 0.09, 8), y: 0.045, tint: 0.6 }, // skirt
    { g: _cyl(T * 0.42, T * 0.42, 0.26, 4), y: 0.20, ry: Math.PI / 4 },
    { g: _box(T * 0.88, 0.15, 0.20), y: 0.40 },
    { g: _box(T * 0.88, 0.15, 0.20), y: 0.40, ry: Math.PI / 2 },
    { g: _cyl(0.17, 0.13, 0.14, 8), y: 0.52 },                   // hub cap
  ]),

  // taller and eight-sided, so a forge is not mistaken for a smelter
  // from across the worldlet
  forge: mergeParts((() => {
    const parts = [
      { g: _cyl(T * 0.56, T * 0.58, 0.11, 8), y: 0.055, tint: 0.6 }, // skirt
      { g: _cyl(T * 0.42, T * 0.50, 1.22, 8), y: 0.72 },         // drum
      { g: new THREE.TorusGeometry(T * 0.40, 0.08, 6, 16), y: 1.30, rx: Math.PI / 2 },
      { g: new THREE.TorusGeometry(T * 0.46, 0.05, 5, 16), y: 0.42, rx: Math.PI / 2 },
    ];
    // vertical ribs: an eight-sided drum with nothing on it reads as a barrel
    for (let k = 0; k < 4; k++) {
      const a = (k / 4) * Math.PI * 2 + Math.PI / 8;
      parts.push({ g: _box(0.09, 1.0, 0.13), y: 0.75,
                   x: Math.cos(a) * T * 0.46, z: Math.sin(a) * T * 0.46, ry: -a });
    }
    return parts;
  })()),
  rift: new THREE.TorusGeometry(T * 0.38, 0.16, 6, 12),
  riftBase: mergeParts([
    { g: _cyl(T * 0.54, T * 0.56, 0.09, 8), y: 0.045, tint: 0.6 }, // skirt
    { g: _cyl(T * 0.44, T * 0.50, 0.20, 8), y: 0.16 },
    { g: _box(0.12, 0.62, 0.12), y: 0.50, x: T * 0.30 },         // supports
    { g: _box(0.12, 0.62, 0.12), y: 0.50, x: -T * 0.30 },
  ]),
  riftCore: new THREE.OctahedronGeometry(0.34, 0),
  filter: mergeParts([
    { g: _box(T * 0.96, 0.10, T * 0.96), y: 0.05, tint: 0.6 },    // skirt
    { g: _box(T * 0.88, 0.20, T * 0.88), y: 0.18 },
    { g: _box(T * 0.16, 0.34, T * 0.66), y: 0.40, x: T * 0.34 }, // sorter housing
    { g: _box(0.10, 0.26, 0.10), y: 0.36, x: -T * 0.36, z: T * 0.36 },
    { g: _box(0.10, 0.26, 0.10), y: 0.36, x: -T * 0.36, z: -T * 0.36 },
  ]),
  filterGate: new THREE.BoxGeometry(T * 0.16, 0.5, T * 0.62),

  // Ground detail. Nothing here is interactive; it exists so the floor has a
  // size. Two kinds is enough — one flat and wide, one small and clustered —
  // because variation at this density comes from rotation and scale far more
  // than from silhouette.
  detailVent: mergeParts([
    { g: _box(T * 0.44, 0.05, T * 0.30), y: 0.025, tint: 0.7 },
    { g: _box(T * 0.34, 0.06, 0.05), y: 0.06, z: -0.16, tint: 0.5 },
    { g: _box(T * 0.34, 0.06, 0.05), y: 0.06, tint: 0.5 },
    { g: _box(T * 0.34, 0.06, 0.05), y: 0.06, z: 0.16, tint: 0.5 },
  ], { floor: 0.55, reach: 0.2 }),
  detailBolts: mergeParts([
    { g: _cyl(T * 0.13, T * 0.14, 0.05, 8), y: 0.025, tint: 0.72 },
    { g: _cyl(0.05, 0.05, 0.07, 6), y: 0.06, x: 0.11, tint: 0.95 },
    { g: _cyl(0.05, 0.05, 0.07, 6), y: 0.06, x: -0.06, z: 0.09, tint: 0.95 },
    { g: _cyl(0.05, 0.05, 0.07, 6), y: 0.06, x: -0.06, z: -0.09, tint: 0.95 },
  ], { floor: 0.55, reach: 0.2 }),
};
// A vertexColors material draws garbage from a geometry with no colour
// attribute, and the same material serves both merged parts and plain boxes —
// so everything gets one, white where nothing was baked.
for (const k in GEO) ensureColors(GEO[k]);

// Vertex colours carry the baked occlusion; the rim is a fresnel pushed into
// emissive so the bloom outlines every machine. Tinted per machine, warm on the
// hot ones and cold on the rest, because a single white rim on everything looks
// like a shader and not like light.
for (const k in MAT) MAT[k].vertexColors = true;
addRim(MAT.miner, 0xff9aa8, 2.6, 0.55);
addRim(MAT.beltFrame, 0x7fffd8, 2.8, 0.40);
addRim(MAT.hub, 0xffe4a8, 2.4, 0.60);
addRim(MAT.smelt, 0xc3aaff, 2.5, 0.55);
addRim(MAT.split, 0xa8ddff, 2.6, 0.50);
addRim(MAT.forge, 0xff9ada, 2.3, 0.65);
addRim(MAT.filt, 0x8fffdd, 2.7, 0.45);
addRim(MAT.rift, 0xc0a8ff, 2.2, 0.70);
for (const m of MINERALS) addRim(nodeMats[m], MIN_COL[m], 2.0, 0.7);

// ── TOOL ICONS ─────────────────────────────────────────────────────────────
// A thumbnail is a render of the machine, not a drawing of one. Done once at
// boot into a 128px target; the whole set costs a few milliseconds and never
// disagrees with the world afterwards.
function renderThumb(obj, size) {
  // AN LDR TARGET, DELIBERATELY. readRenderTargetPixels has to be handed the
  // buffer type the texture actually uses — a HalfFloat target wants a
  // Uint16Array, and both a Uint8Array and a Float32Array come back empty
  // without throwing, which shows up as eight blank squares in the tool bar
  // and nothing in the console. Bytes clip the highlights on a 38px icon,
  // which nobody will ever see.
  const rt = new THREE.WebGLRenderTarget(size, size, { depthBuffer: true });
  const sc = new THREE.Scene();
  sc.environment = scene.environment;
  sc.add(new THREE.HemisphereLight(0xcfe0ff, 0x2a3050, 1.5));
  const key = new THREE.DirectionalLight(0xfff4e2, 2.9);
  key.position.set(4, 6, 5); sc.add(key);
  const rim = new THREE.DirectionalLight(0x8fd8ff, 1.5);
  rim.position.set(-5, 2, -4); sc.add(rim);
  sc.add(obj);

  // frame it: bounding sphere, then back off far enough to fit with a margin
  const box = new THREE.Box3().setFromObject(obj);
  const c = box.getCenter(new THREE.Vector3());
  const r = Math.max(0.001, box.getSize(new THREE.Vector3()).length() * 0.5);
  const cam = new THREE.PerspectiveCamera(30, 1, 0.01, 200);
  const d = (r / Math.sin(15 * Math.PI / 180)) * 0.82;
  cam.position.set(c.x + d * 0.62, c.y + d * 0.52, c.z + d * 0.59);
  cam.lookAt(c);

  const prevTarget = renderer.getRenderTarget();
  const prevAlpha = renderer.getClearAlpha();
  renderer.setClearAlpha(0);
  renderer.setRenderTarget(rt);
  renderer.clear();
  renderer.render(sc, cam);
  // A FLOAT TARGET NEEDS A FLOAT BUFFER (2026-09-08). Reading a HalfFloat
  // render target into a Uint8Array is a type mismatch: it returns nothing
  // useful and throws nothing, so every icon came out blank and the only
  // symptom was an empty square in the bar.
  const buf = new Uint8Array(size * size * 4);
  renderer.readRenderTargetPixels(rt, 0, 0, size, size, buf);
  renderer.setRenderTarget(prevTarget);
  renderer.setClearAlpha(prevAlpha);

  const cv = document.createElement('canvas');
  cv.width = cv.height = size;
  const g2 = cv.getContext('2d');
  const img = g2.createImageData(size, size);
  const aces = x => {
    const v = x * 1.06;
    return Math.max(0, Math.min(1, (v * (2.51 * v + 0.03)) / (v * (2.43 * v + 0.59) + 0.14)));
  };
  const srgb = x => x <= 0.0031308 ? x * 12.92 : 1.055 * Math.pow(x, 1 / 2.4) - 0.055;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      // readRenderTargetPixels is bottom-origin, ImageData is top-origin
      const src = ((size - 1 - y) * size + x) * 4;
      const dst = (y * size + x) * 4;
      const a = buf[src + 3] / 255;
      for (let k = 0; k < 3; k++) {
        // un-premultiply, then the same tone map and encode the main composite
        // does — a render target is linear and nobody converts it for you
        let v = buf[src + k] / 255;
        if (a > 0.004) v /= a;
        img.data[dst + k] = Math.round(srgb(aces(v)) * 255);
      }
      img.data[dst + 3] = buf[src + 3];
    }
  }
  g2.putImageData(img, 0, 0);
  rt.dispose();
  return cv.toDataURL('image/png');
}

function buildToolIcons() {
  const mk = (geo, mat) => new THREE.Mesh(geo, mat);
  const grp = list => { const g = new THREE.Group();
                        for (const o of list) g.add(o); return g; };
  const SET = {
    miner: () => grp([mk(GEO.miner, MAT.miner),
                      (() => { const b = mk(GEO.minerBit, MAT.miner);
                               b.position.y = 0.42; return b; })()]),
    belt: () => grp([mk(GEO.beltFrame, MAT.beltFrame),
                     (() => { const d = mk(GEO.beltDeck, MAT.beltDeck);
                              d.position.y = 0.155; return d; })()]),
    smelter: () => mk(GEO.smelt, MAT.smelt),
    splitter: () => mk(GEO.split, MAT.split),
    hub: () => mk(GEO.hub, MAT.hub),
    forge: () => mk(GEO.forge, MAT.forge),
    filter: () => mk(GEO.filter, MAT.filt),
    rift: () => grp([mk(GEO.riftBase, MAT.rift),
                     (() => { const r = mk(GEO.rift, MAT.rift);
                              r.position.y = 0.95; r.rotation.x = Math.PI / 2;
                              return r; })()]),
  };
  // the stat chips too: a miner is the same picture everywhere it appears.
  // Items and cores are not machines, so they get their own small renders.
  const CHIP = {
    miner: SET.miner, belt: SET.belt, smelter: SET.smelter,
    item: () => mk(new THREE.OctahedronGeometry(0.5, 0), nodeMats[CRYSTAL]),
    ingot: () => mk(new THREE.BoxGeometry(0.9, 0.35, 0.5),
      new THREE.MeshStandardMaterial({ color: 0xffae4d, emissive: 0x7a4a10,
        emissiveIntensity: 0.8, metalness: 0.7, roughness: 0.3 })),
    alloy: () => mk(new THREE.OctahedronGeometry(0.5, 1),
      new THREE.MeshStandardMaterial({ color: 0xff5ad9, emissive: 0x8a1a6a,
        emissiveIntensity: 0.9, metalness: 0.6, roughness: 0.25 })),
    core: () => mk(new THREE.IcosahedronGeometry(0.5, 0),
      new THREE.MeshStandardMaterial({ color: 0xffd479, emissive: 0xa06a10,
        emissiveIntensity: 1.1, metalness: 0.8, roughness: 0.2 })),
  };
  for (const name in CHIP) {
    const el = document.querySelector('.st[data-ico="' + name + '"] i');
    if (!el) continue;
    let url = null;
    try { url = renderThumb(CHIP[name](), 64); } catch (e) { url = null; }
    if (url) el.style.backgroundImage = 'url(' + url + ')';
  }
  for (const name in SET) {
    const el = document.querySelector('.tool[data-tool="' + name + '"]');
    if (!el) continue;
    let url = null;
    try { url = renderThumb(SET[name](), 128); } catch (e) { url = null; }
    if (!url) continue;                    // the drawn fallback stays in place
    const img = document.createElement('img');
    img.className = 'ico';
    img.src = url;
    img.alt = name;
    const svg = el.querySelector('svg');
    if (svg) svg.replaceWith(img); else el.prepend(img);
  }
}

function refreshCounts() {
  let m = 0, b = 0, sm = 0;
  eachTile(c => {
    if (c.t === MINER) m++;
    else if (c.t === BELT) b++;
    else if (c.t === SMELTER) sm++;
  });
  document.getElementById('nmine').textContent = m;
  document.getElementById('nbelt').textContent = b;
  document.getElementById('nsmelt').textContent = sm;
}

function removeAt(face, i, j) {
  const c = cells[face][i][j];
  beltsDirty = true;
  if (c.build) { scene.remove(c.build); c.build = null; }
  c.t = c.mesh ? NODE : EMPTY;               // a node outlives its miner
  c.item = 0;
  refreshCounts();
}

function place(face, i, j, type, dir) {
  const c = cells[face][i][j];
  if (type === MINER && c.t !== NODE && c.t !== MINER) return false;
  // REFUSE A TYPE THIS FACTORY DOES NOT BUILD (2026-09-07). place() used to
  // fall off the end of its if-chain for an unrecognised type and set
  // c.t = undefined: an invisible machine that no rule matched and no counter
  // saw. Nothing threw; the tile just quietly stopped being part of the game.
  if (!TYPE_NAME[type]) return false;
  c.buf = 0; c.bt = 0; c.fa = 0; c.fb = 0; c.cook = 0;
  if (type !== MINER && c.t === NODE) return false;      // keep nodes clear
  if (c.build) { scene.remove(c.build); c.build = null; }
  const g = new THREE.Group();
  if (type === MINER) {
    const b = new THREE.Mesh(GEO.miner, MAT.miner);
    b.castShadow = true; g.add(b);
    // the bit turns while the rig is on a seam: the only moving part on a
    // machine that otherwise just sits there
    const bit = new THREE.Mesh(GEO.minerBit, MAT.miner);
    bit.position.y = 0.42; bit.name = 'bit'; g.add(bit);
  } else if (type === BELT) {
    // belts are drawn as instances, not as objects — see rebuildBelts()
  } else if (type === HUB) {
    const b = new THREE.Mesh(GEO.hub, MAT.hub);
    b.castShadow = true; g.add(b);
    const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.15, 8, 6),
      new THREE.MeshBasicMaterial({ color: 0xffd479 }));
    beacon.position.y = 1.22; beacon.name = 'lamp'; g.add(beacon);
    // the price board, on the mast, facing the way the hub faces: the thing
    // that pays the prices is the thing that displays them
    const board = new THREE.Mesh(new THREE.PlaneGeometry(0.9, 0.45),
      new THREE.MeshBasicMaterial({ map: TICK_TEX, transparent: false }));
    board.position.set(0.12, 0.82, 0);
    board.rotation.y = Math.PI / 2;
    board.name = 'board';
    g.add(board);
  } else if (type === SPLITTER) {
    // a cross, so what it does is visible from across the worldlet rather than
    // being a box you have to remember the meaning of
    const b = new THREE.Mesh(GEO.split, MAT.split);
    b.castShadow = true; b.receiveShadow = true; b.name = 'spin'; g.add(b);
  } else if (type === RIFT) {
    const ring = new THREE.Mesh(GEO.rift, MAT.rift);
    ring.position.y = 0.95; ring.rotation.x = Math.PI / 2;
    ring.castShadow = true; ring.name = 'ring'; g.add(ring);
    const core = new THREE.Mesh(GEO.riftCore,
      new THREE.MeshBasicMaterial({ color: 0x2a2050 }));
    core.position.y = 0.95; core.name = 'lamp'; g.add(core);
    const base = new THREE.Mesh(GEO.riftBase, MAT.rift);
    base.receiveShadow = true; g.add(base);
  } else if (type === FILTER) {
    const b = new THREE.Mesh(GEO.filter, MAT.filt);
    b.castShadow = true; b.receiveShadow = true; g.add(b);
    // the gate is coloured with the ore that passes, so a filter's setting is
    // readable from across the face instead of from a tooltip
    const gate = new THREE.Mesh(GEO.filterGate,
      new THREE.MeshStandardMaterial({ color: MIN_COL[c.filt] || 0x7df9ff,
        emissive: MIN_COL[c.filt] || 0x7df9ff, emissiveIntensity: 0.5,
        roughness: 0.3, flatShading: true }));
    gate.position.set(0.36, 0.42, 0);
    gate.name = 'gate';
    g.add(gate);
    const r = new THREE.Mesh(GEO.arrow, MAT.filt);   // reject: out the side
    r.position.set(0, 0.42, 0.74); r.rotation.x = Math.PI / 2; g.add(r);
  } else if (type === FORGE) {
    const b = new THREE.Mesh(GEO.forge, MAT.forge);
    b.castShadow = true; g.add(b);
    const halo = new THREE.Mesh(new THREE.TorusGeometry(T * 0.41, 0.05, 6, 18),
      new THREE.MeshBasicMaterial({ color: 0xff5ad9 }));
    halo.position.y = 1.30; halo.rotation.x = Math.PI / 2;
    halo.name = 'halo'; halo.visible = false; g.add(halo);
    const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.17, 8, 6),
      new THREE.MeshBasicMaterial({ color: 0xff5ad9 }));
    lamp.position.set(0, 1.5, 0);
    lamp.name = 'lamp';
    g.add(lamp);
  } else if (type === SMELTER) {
    const b = new THREE.Mesh(GEO.smelt, MAT.smelt);
    b.castShadow = true; g.add(b);
    // a lamp that lights while it is cooking: a factory you can read at a
    // glance from across the island is the whole appeal of the genre
    // THE DOOR IS THE LAMP. A bulb on the roof told you a smelter was working;
    // a furnace door glowing where the heat is tells you the same thing and
    // looks like a furnace while doing it.
    const lamp = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.32, T * 0.26),
      new THREE.MeshBasicMaterial({ color: 0xffb04a }));
    lamp.position.set(T * 0.47, 0.50, 0);
    lamp.name = 'lamp';
    g.add(lamp);
  }
  seat(g, face, i, j, dir, 0);
  if (typeof sfxPlace === 'function') sfxPlace();
  // what the studio's inspector reads when you click this. Same shape the
  // adventure runtime uses, so one panel renders picks from either genre.
  g.userData.fsTag = { type: 'machine', name: TYPE_NAME[type] || 'machine',
                       detail: FACES[face].name + ' face · tile ' + i + ',' + j,
                       face, i, j };
  // EVERY placement is dirty now, not just belts: the contact shadows are
  // rebuilt in the same pass and a smelter needs one as much as a belt does.
  beltsDirty = true;
  if (type !== BELT) scene.add(g);
  c.build = type === BELT ? null : g;
  c.t = type;
  c.d = dir;
  c.item = 0;
  refreshCounts();
  return true;
}

// ── belts: ONE InstancedMesh pair, however many you build ──────────────────
// 241 belts cost 482 draw calls as individual groups, before any detail was
// added. As instances they cost two, and the art pass became affordable.
const MAX_BELTS = 6000;
// three shapes, six batches. A belt is either straight or turning one of two
// ways, and which one it is depends on where its input comes from — so the
// shape is a property of the LAYOUT, not of the tile, and it has to be
// recomputed whenever anything around it changes.
const BELT_KIND = ['', 'A', 'B', 'J'];
const beltFrames = [], beltDecks = [], beltIndex = BELT_KIND.map(() => []);
for (let k = 0; k < BELT_KIND.length; k++) {
  const fm = new THREE.InstancedMesh(GEO['beltFrame' + BELT_KIND[k]],
                                     MAT.beltFrame, MAX_BELTS);
  // a junction runs straight through, so it wears the straight deck
  const dk = new THREE.InstancedMesh(GEO['beltDeck' + BELT_KIND[k]] || GEO.beltDeck,
                                     MAT.beltDeck, MAX_BELTS);
  dk.instanceColor = new THREE.InstancedBufferAttribute(
    new Float32Array(MAX_BELTS * 3).fill(1), 3);
  dk.instanceColor.setUsage(THREE.DynamicDrawUsage);
  for (const m of [fm, dk]) {
    m.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    m.frustumCulled = false;
    m.castShadow = true; m.receiveShadow = true;
    m.count = 0;
    scene.add(m);
  }
  beltFrames.push(fm); beltDecks.push(dk);
}
let beltsDirty = true;

/**
 * Which way does an item arrive at this belt? Whichever neighbour points AT it.
 * A tile with no feeder, or more than one, is drawn straight: a corner piece
 * that guessed would be wrong half the time, and a straight one is never
 * actively misleading.
 */
function beltShape(f, i, j, c) {
  let inbound = -1, found = 0;
  for (let d = 0; d < 4; d++) {
    if (d === c.d) continue;                       // that side is the output
    const nb = stepTile(f, i, j, d);
    const src = cellOf(nb);
    if (!src) continue;
    if (src.t !== BELT && src.t !== MINER && src.t !== FILTER &&
        src.t !== SMELTER && src.t !== FORGE && src.t !== RIFT) continue;
    const out = stepTile(nb.face, nb.i, nb.j, src.d);
    if (!out || out.face !== f || out.i !== i || out.j !== j) continue;
    inbound = (d + 2) % 4;                          // travel direction into us
    found++;
  }
  if (found > 1) return 3;                          // a merge
  if (found !== 1 || inbound === c.d) return 0;
  const turn = (c.d - inbound + 4) % 4;
  return turn === 3 ? 1 : turn === 1 ? 2 : 0;       // 1 = A, 2 = B, 0 = straight
}

function rebuildBelts() {
  // one counter per belt shape — straight, two turns, junction. Sized by
  // hand once too often: a fourth shape with a three-slot counter set its
  // instance count to undefined, and undefined belts draw as nothing.
  const n = BELT_KIND.map(() => 0);
  let d = 0, sv = 0, sb = 0;
  for (const a of beltIndex) a.length = 0;
  eachTile((c, f, i, j) => {
    const w = DECAL_W[c.t];
    if (w && d < MAX_DECALS) {
      // the plane is authored face-up in its own frame, so seating it and then
      // laying it flat puts it on whichever face the machine is standing on
      seatMatrix(f, i, j, c.d, 0.03, _dm);
      _dpos.setFromMatrixPosition(_dm);
      _dq.setFromRotationMatrix(_dm).multiply(_flat);
      _dscale.set(T * w, T * w, 1);
      _dm.compose(_dpos, _dq, _dscale);
      decals.setMatrixAt(d++, _dm);
    }
    if (c.t !== BELT) return;
    const k = beltShape(f, i, j, c);
    if (n[k] >= MAX_BELTS) return;
    // the corner shapes bake their own height in, so both batches seat at zero
    seatMatrix(f, i, j, c.d, 0, _mx);
    beltFrames[k].setMatrixAt(n[k], _mx);
    if (k === 0 || k === 3) seatMatrix(f, i, j, c.d, 0.155, _mx);
    beltDecks[k].setMatrixAt(n[k], _mx);
    beltIndex[k][n[k]] = { face: f, i, j };
    n[k]++;
  });
  // ground detail, minus anything now standing on it
  for (const sp of scatterSpots) {
    const c = cells[sp.f][sp.i][sp.j];
    if (c.t !== EMPTY) continue;
    seatMatrix(sp.f, sp.i, sp.j, sp.d, 0.02, _dm);
    _dpos.setFromMatrixPosition(_dm);
    _dq.setFromRotationMatrix(_dm);
    _dscale.setScalar(sp.s);
    _dm.compose(_dpos, _dq, _dscale);
    if (sp.kind === 0) { if (sv < MAX_SCATTER) scatterVent.setMatrixAt(sv++, _dm); }
    else if (sb < MAX_SCATTER) scatterBolt.setMatrixAt(sb++, _dm);
  }
  scatterVent.count = sv; scatterBolt.count = sb;
  scatterVent.instanceMatrix.needsUpdate = true;
  scatterBolt.instanceMatrix.needsUpdate = true;

  for (let k = 0; k < BELT_KIND.length; k++) {
    beltFrames[k].count = n[k]; beltDecks[k].count = n[k];
    beltFrames[k].instanceMatrix.needsUpdate = true;
    beltDecks[k].instanceMatrix.needsUpdate = true;
  }
  decals.count = d;
  decals.instanceMatrix.needsUpdate = true;
  beltsDirty = false;
}

/** A throwable stand-in for a machine that is drawn as an instance. */
function pieceFor(face, i, j, c) {
  if (c.build) return c.build;
  if (c.t !== BELT) return null;
  const g = new THREE.Mesh(GEO.beltFrame, MAT.beltFrame);
  seat(g, face, i, j, c.d, 0);
  scene.add(g);
  return g;
}

// ── CONTACT SHADOWS ────────────────────────────────────────────────────────
// One directional light can only shadow the three faces it lights; walk around
// the corner and the factory is hovering again. A soft dark disc under every
// machine grounds it on all six, and reads as the ambient occlusion a real
// renderer would compute. One instanced batch for the whole worldlet.
function contactTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 64;
  const g = c.getContext('2d');
  const grd = g.createRadialGradient(32, 32, 2, 32, 32, 31);
  // AS STRONG AS THE CAST SHADOW IT STANDS IN FOR. Measured against the real
  // one on a lit face, the first version darkened a quarter as much, so a
  // machine on the underside still read as floating next to an identical
  // machine on top that did not.
  grd.addColorStop(0, 'rgba(0,0,0,0.86)');
  grd.addColorStop(0.45, 'rgba(0,0,0,0.62)');
  grd.addColorStop(0.78, 'rgba(0,0,0,0.22)');
  grd.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = grd; g.fillRect(0, 0, 64, 64);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}
// ── GROUND DETAIL ──────────────────────────────────────────────────────────
// Seeded from the same RNG the ore uses, so a given world always looks like
// itself; instanced, so several hundred pieces cost two draw calls; and hidden
// under anything built on their tile, because a vent poking through a smelter
// is worse than no vent at all.
const MAX_SCATTER = 900;
const scatterMats = new THREE.MeshStandardMaterial({
  color: 0x707ba8, roughness: 0.82, metalness: 0.3,
  vertexColors: true, envMapIntensity: 0.6 });
const scatterVent = new THREE.InstancedMesh(GEO.detailVent, scatterMats, MAX_SCATTER);
const scatterBolt = new THREE.InstancedMesh(GEO.detailBolts, scatterMats, MAX_SCATTER);
for (const m of [scatterVent, scatterBolt]) {
  m.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  m.frustumCulled = false;
  m.receiveShadow = true;
  m.count = 0;
  scene.add(m);
}

const MAX_DECALS = 6000;
const decals = new THREE.InstancedMesh(
  new THREE.PlaneGeometry(1, 1),
  new THREE.MeshBasicMaterial({ map: contactTexture(), transparent: true,
    depthWrite: false, fog: true, opacity: 0.95 }),
  MAX_DECALS);
decals.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
decals.frustumCulled = false;
decals.renderOrder = 1;              // after the ground, before the machines
decals.count = 0;
decals.name = 'contact';
scene.add(decals);

// how wide a machine's shadow is. A belt is nearly flat and casts a thin one;
// a drill rig on legs casts a wide soft one.
// Wider than the machine that casts it, because a contact shadow that stops at
// the footprint reads as a dark mat someone put down rather than as light being
// blocked. A belt's is narrow and long-ish; a rig on legs throws a broad soft one.
const DECAL_W = { 1: 1.8, 2: 1.25, 3: 1.9, 5: 1.85, 6: 1.55, 7: 1.75,
                  8: 1.25, 9: 1.7 };

const _dq = new THREE.Quaternion();
const _dm = new THREE.Matrix4();
const _dpos = new THREE.Vector3(), _dscale = new THREE.Vector3();
const _flat = new THREE.Quaternion().setFromEuler(new THREE.Euler(-Math.PI / 2, 0, 0));

// ── SMOKE AND SPARKS ───────────────────────────────────────────────────────
// One system, two jobs. Two particle systems doing the same arithmetic with
// different constants is how a codebase ends up with two subtly different
// gravities, and how one of them ends up wrong on the underside of the cube.
const PMAX = 420;
const pPos = new Float32Array(PMAX * 3);
const pVel = new Float32Array(PMAX * 3);
const pCol = new Float32Array(PMAX * 3);
const pLife = new Float32Array(PMAX);      // 1 at birth, 0 at death
const pDecay = new Float32Array(PMAX);
const pSize = new Float32Array(PMAX);
let pHead = 0;

const partGeo = new THREE.BufferGeometry();
partGeo.setAttribute('position', new THREE.BufferAttribute(pPos, 3));
partGeo.setAttribute('aColor', new THREE.BufferAttribute(pCol, 3));
partGeo.setAttribute('aLife', new THREE.BufferAttribute(pLife, 1));
partGeo.setAttribute('aSize', new THREE.BufferAttribute(pSize, 1));
const partMat = new THREE.ShaderMaterial({
  transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
  vertexShader: `
    attribute vec3 aColor; attribute float aLife; attribute float aSize;
    varying vec3 vCol; varying float vLife;
    void main() {
      vCol = aColor; vLife = aLife;
      vec4 mv = modelViewMatrix * vec4(position, 1.0);
      // smoke swells as it dies, sparks shrink: aSize carries the sign
      float grow = aSize > 0.0 ? (1.6 - 0.9 * aLife) : aLife;
      gl_PointSize = abs(aSize) * grow * 300.0 / max(1.0, -mv.z);
      gl_Position = projectionMatrix * mv;
    }`,
  fragmentShader: `
    varying vec3 vCol; varying float vLife;
    void main() {
      vec2 d = gl_PointCoord - 0.5;
      float r2 = dot(d, d);
      if (r2 > 0.25) discard;                 // round, not square
      float a = (1.0 - smoothstep(0.0, 0.25, r2)) * vLife;
      gl_FragColor = vec4(vCol * a, a);
    }`,
});
const particles = new THREE.Points(partGeo, partMat);
particles.frustumCulled = false;
particles.name = 'particles';
scene.add(particles);

/** Emit one particle. size > 0 swells (smoke), size < 0 shrinks (spark). */
function emit(x, y, z, vx, vy, vz, r, g, bcol, size, decay) {
  const k = pHead; pHead = (pHead + 1) % PMAX;
  pPos[k * 3] = x; pPos[k * 3 + 1] = y; pPos[k * 3 + 2] = z;
  pVel[k * 3] = vx; pVel[k * 3 + 1] = vy; pVel[k * 3 + 2] = vz;
  pCol[k * 3] = r; pCol[k * 3 + 1] = g; pCol[k * 3 + 2] = bcol;
  pLife[k] = 1; pDecay[k] = decay; pSize[k] = size;
}

function stepParticles(dt) {
  let alive = 0;
  for (let k = 0; k < PMAX; k++) {
    if (pLife[k] <= 0) continue;
    pLife[k] -= dt * pDecay[k];
    if (pLife[k] <= 0) { pLife[k] = 0; pSize[k] = 0; continue; }
    pPos[k * 3] += pVel[k * 3] * dt;
    pPos[k * 3 + 1] += pVel[k * 3 + 1] * dt;
    pPos[k * 3 + 2] += pVel[k * 3 + 2] * dt;
    // drag, so nothing flies off in a straight line forever — scaled by how
    // fast the particle is dying, so a spark (decay ~2.5) is braked hard and a
    // snowflake (decay ~0.12) keeps falling
    const f = 1 - Math.min(1, dt * 1.1 * Math.min(1, pDecay[k] * 0.6));
    pVel[k * 3] *= f; pVel[k * 3 + 1] *= f; pVel[k * 3 + 2] *= f;
    alive++;
  }
  partGeo.attributes.position.needsUpdate = true;
  partGeo.attributes.aLife.needsUpdate = true;
  partGeo.attributes.aColor.needsUpdate = true;
  partGeo.attributes.aSize.needsUpdate = true;
  return alive;
}

// WEATHER. A volume above the face the player is standing on, refilled at the
// world's own rate. Positive `fall` sinks toward the face, negative rises off
// it — spores go up. Drift is sideways sway, in the face's own tangent frame,
// so it is sideways on the underside of the cube too.
let weatherClock = 0;
function stepWeather(dt) {
  const w = WORLDS[worldIdx] && WORLDS[worldIdx].weather;
  if (!w || intro > 0) return;
  weatherClock += dt * w.rate;
  const f = FACES[player.face], n = f.n, u = f.u, v = f.v;
  while (weatherClock >= 1) {
    weatherClock -= 1;
    // a disc around the player, 14m across, 2-9m above the face
    const a = Math.random() * Math.PI * 2, r = Math.sqrt(Math.random()) * 14;
    const du = Math.cos(a) * r, dv = Math.sin(a) * r;
    const h = w.fall >= 0 ? 2 + Math.random() * 7 : 0.2 + Math.random() * 1.5;
    const px = player.pos.x + u[0] * du + v[0] * dv + n[0] * (h - EYE);
    const py = player.pos.y + u[1] * du + v[1] * dv + n[1] * (h - EYE);
    const pz = player.pos.z + u[2] * du + v[2] * dv + n[2] * (h - EYE);
    const sway = (Math.random() - 0.5) * w.drift, sway2 = (Math.random() - 0.5) * w.drift;
    emit(px, py, pz,
         -n[0] * w.fall + u[0] * sway + v[0] * sway2,
         -n[1] * w.fall + u[1] * sway + v[1] * sway2,
         -n[2] * w.fall + u[2] * sway + v[2] * sway2,
         w.col[0], w.col[1], w.col[2], w.size, w.life);
  }
}

// Emitters live where the machines are, and every one of them pushes UP off
// the face rather than up in the world — smoke that rises toward +Y on the
// underside of the cube would fall into the ground.
let emitClock = 0;
function stepEmitters(dt) {
  emitClock += dt;
  if (emitClock < 0.055) return;
  emitClock = 0;
  eachTile((c, f, i, j) => {
    if (c.t === SMELTER && c.cook > 0) {
      if (Math.random() > 0.34) return;
      const n = FACES[f].n, w = tileWorld(f, i, j), u = FACES[f].u, v = FACES[f].v;
      // the flue sits at (+0.22T, -0.22T) in the machine's own frame
      const ox = u[0] * T * 0.22 - v[0] * T * 0.22;
      const oy = u[1] * T * 0.22 - v[1] * T * 0.22;
      const oz = u[2] * T * 0.22 - v[2] * T * 0.22;
      const sp = 0.9 + Math.random() * 0.7;
      emit(w[0] + ox + n[0] * 1.75, w[1] + oy + n[1] * 1.75, w[2] + oz + n[2] * 1.75,
           n[0] * sp + (Math.random() - 0.5) * 0.4,
           n[1] * sp + (Math.random() - 0.5) * 0.4,
           n[2] * sp + (Math.random() - 0.5) * 0.4,
           // ADDITIVE, so a dark grey adds almost nothing. Smoke against a
           // starfield has to be brighter than smoke against daylight.
           0.44, 0.42, 0.52, 0.10, 0.7);
    } else if (c.t === MINER) {
      if (Math.random() > 0.22) return;
      const n = FACES[f].n, w = tileWorld(f, i, j);
      const sp = 1.6 + Math.random() * 1.8;
      const col = MIN_COL[c.min || CRYSTAL];
      const cr = ((col >> 16) & 255) / 255, cg = ((col >> 8) & 255) / 255,
            cb = (col & 255) / 255;
      // ALONG THE FACE NORMAL, not along world +Y. Written the lazy way, a
      // drill on the underside of the cube throws its sparks into the ground.
      emit(w[0] + n[0] * 0.45, w[1] + n[1] * 0.45, w[2] + n[2] * 0.45,
           n[0] * 1.3 + (Math.random() - 0.5) * sp,
           n[1] * 1.3 + (Math.random() - 0.5) * sp,
           n[2] * 1.3 + (Math.random() - 0.5) * sp,
           cr, cg, cb, -0.045, 2.3);
    }
  });
}

// ── items: one InstancedMesh for every crystal in transit ──────────────────
const MAX_ITEMS = 4000;
const items = new THREE.InstancedMesh(
  new THREE.OctahedronGeometry(0.26, 0),
  new THREE.MeshStandardMaterial({ color: 0x7df9ff, emissive: 0x2aa6c4,
    emissiveIntensity: 1.4, roughness: 0.3, flatShading: true }),
  MAX_ITEMS);
items.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
items.frustumCulled = false;
items.count = 0;
// One mesh still, but two products: instanceColor is what lets a single draw
// call carry both. Reading a belt at a glance — "that line is running ingots,
// that one is still raw" — is most of what makes a factory legible.
items.instanceColor = new THREE.InstancedBufferAttribute(
  new Float32Array(MAX_ITEMS * 3), 3);
items.instanceColor.setUsage(THREE.DynamicDrawUsage);
scene.add(items);
const ITEM_COL = {
  [CRYSTAL]: new THREE.Color(0x7df9ff),
  [EMBER]: new THREE.Color(0xff8a3d),
  [SALT]: new THREE.Color(0xe8f0ff),
  [INGOT]: new THREE.Color(0x9fd6ff),
  [INGOT_E]: new THREE.Color(0xffae4d),
  [INGOT_S]: new THREE.Color(0xd8e2f5),
  [ALLOY]: new THREE.Color(0xff5ad9),
};

const _m = new THREE.Matrix4();
const _p = new THREE.Vector3();
const _q = new THREE.Quaternion();
const _s = new THREE.Vector3(1, 1, 1);
const _up = new THREE.Vector3(0, 1, 0);   // reused per item: the face normal

// ── the tick: belts advance, miners feed, the hub banks ────────────────────
let ore = 0;
let ingots = 0;
let alloys = 0;

// ── THE MARKET ─────────────────────────────────────────────────────────────
// A price per traded good, drifting on a mean-reverting random walk. The hub
// pays the live rate, so "which ingot should this line be making" becomes a
// question with an answer that changes — which is the thing a single-recipe
// factory can never have. The filter tile is how you act on it.
const TRADED = [INGOT, INGOT_E, INGOT_S, ALLOY];
const TRADE_NAME = { [INGOT]: 'crystal', [INGOT_E]: 'ember',
                     [INGOT_S]: 'salt', [ALLOY]: 'alloy' };
const TRADE_COL = { [INGOT]: '#9fd6ff', [INGOT_E]: '#ffae4d',
                    [INGOT_S]: '#d8e2f5', [ALLOY]: '#ff5ad9' };
const PRICE = {}, LAST_PRICE = {};
for (const t of TRADED) { PRICE[t] = 1; LAST_PRICE[t] = 1; }
const PRICE_MIN = 0.55, PRICE_MAX = 1.85;
let priceClock = 0;

function stepMarket(dt) {
  priceClock += dt;
  if (priceClock < 3.5) return;
  priceClock = 0;
  for (const t of TRADED) {
    LAST_PRICE[t] = PRICE[t];
    // mean reversion keeps a long session from parking every price at a rail,
    // which would quietly turn the market back off
    const drift = (1 - PRICE[t]) * 0.12;
    const shock = (Math.random() - 0.5) * 0.34;
    PRICE[t] = Math.max(PRICE_MIN, Math.min(PRICE_MAX, PRICE[t] + drift + shock));
  }
  renderTicker();
}

// One texture for every hub's board. Drawn here, in the same call that
// redraws the panel, so the world and the HUD never disagree about a price.
const TICK_TEX = (() => {
  const c = document.createElement('canvas');
  c.width = 128; c.height = 64;
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.userData.canvas = c;
  return t;
})();
function drawTickerBoard() {
  const c = TICK_TEX.userData.canvas, g = c.getContext('2d');
  g.fillStyle = '#0b1020'; g.fillRect(0, 0, 128, 64);
  g.strokeStyle = 'rgba(120,200,255,0.35)'; g.lineWidth = 2; g.strokeRect(1, 1, 126, 62);
  TRADED.forEach((t, k) => {
    const h = Math.round(((PRICE[t] - PRICE_MIN) / (PRICE_MAX - PRICE_MIN)) * 40 + 6);
    g.fillStyle = TRADE_COL[t];
    g.fillRect(10 + k * 30, 56 - h, 20, h);
  });
  TICK_TEX.needsUpdate = true;
}

function renderTicker() {
  drawTickerBoard();
  const box = document.getElementById('tick');
  if (!box) return;
  // FOUR BARS, NOT FOUR NUMBERS. Height is price, colour is the ore, so the
  // best thing to be making right now is simply the tallest bar — a decision
  // you can make from across the room instead of by comparing decimals.
  let html = '';
  for (const t of TRADED) {
    const up = PRICE[t] >= LAST_PRICE[t];
    const hgt = Math.round(((PRICE[t] - PRICE_MIN) / (PRICE_MAX - PRICE_MIN)) * 34 + 6);
    html += '<div class="mk ' + (up ? 'u' : 'd') + '">' +
      '<span class="px">' + PRICE[t].toFixed(2) + '</span>' +
      '<div class="bar" style="height:' + hgt + 'px;background:' + TRADE_COL[t] + '"></div>' +
      '<span class="nm">' + TRADE_NAME[t] + '</span></div>';
  }
  box.innerHTML = html;
}
let sinceTick = 0;
let minedWindow = 0;
let rateWindow = 0;
const rateBuckets = [];
const sparkHist = [];            // one entry per second, the last forty
function drawSpark() {
  const cv = document.getElementById('spark');
  if (!cv) return;
  const g = cv.getContext('2d'), W = cv.width, H = cv.height;
  g.clearRect(0, 0, W, H);
  if (sparkHist.length < 2) return;
  const max = Math.max(1, ...sparkHist);
  // area first, line on top: the fill is what makes it read as a quantity
  g.beginPath();
  for (let k = 0; k < sparkHist.length; k++) {
    const x = (k / 39) * (W - 2) + 1;
    const y = H - 3 - (sparkHist[k] / max) * (H - 8);
    if (k === 0) g.moveTo(x, y); else g.lineTo(x, y);
  }
  const lastX = ((sparkHist.length - 1) / 39) * (W - 2) + 1;
  g.lineTo(lastX, H); g.lineTo(1, H); g.closePath();
  const grd = g.createLinearGradient(0, 0, 0, H);
  grd.addColorStop(0, 'rgba(255,212,121,0.42)');
  grd.addColorStop(1, 'rgba(255,212,121,0.02)');
  g.fillStyle = grd; g.fill();
  g.beginPath();
  for (let k = 0; k < sparkHist.length; k++) {
    const x = (k / 39) * (W - 2) + 1;
    const y = H - 3 - (sparkHist[k] / max) * (H - 8);
    if (k === 0) g.moveTo(x, y); else g.lineTo(x, y);
  }
  g.strokeStyle = '#ffd479'; g.lineWidth = 1.5; g.lineJoin = 'round'; g.stroke();
}
let lastOreShown = -1;

function bank(type) {
  // the market only prices refined goods; raw ore always sells for its base
  const v = (VALUE[type] || 1) * (PRICE[type] || 1);
  ore += v; runValue += v;
  if (IS_INGOT(type)) ingots++;
  if (type === ALLOY) alloys++;
}

// One acceptance rule, asked by belts, miners and splitters alike. Having each
// of them decide separately is how a factory sim ends up with items that can
// enter a machine one way and not another for no reason the player can see.
function accepts(dst, type) {
  if (!dst) return false;
  if (dst.t === HUB) return true;
  if (dst.t === BELT || dst.t === SPLITTER || dst.t === FILTER) return !dst.item;
  // A smelter refines ONE kind at a time — mixing two ores in it would make
  // the alloy free, and the alloy is supposed to cost a trip across an edge.
  if (dst.t === SMELTER)
    return IS_MINERAL(type) && dst.buf < SMELT_IN * 2 &&
           (dst.buf === 0 || dst.bt === type);
  // A forge is the opposite rule: it wants two DIFFERENT minerals, so it
  // cannot be fed from a single face.
  if (dst.t === FORGE)
    return IS_MINERAL(type) && dst.cook === 0 &&
           (dst.fa === 0 || (dst.fb === 0 && type !== dst.fa));
  // a rift only takes back exactly what it lent — anything else rides past it,
  // which is what makes the filter tile the tool for repaying one
  if (dst.t === RIFT) return dst.dbt > 0 && type === dst.dmin;
  return false;
}
// `to` is the tile it landed on. Passing it costs nothing and is what lets an
// arrival be a visible event rather than a counter changing in the corner.
function deliver(dst, to, type) {
  // a machine eating something should be visible from outside it
  if (to && (dst.t === SMELTER || dst.t === FORGE || dst.t === RIFT)) {
    const n = FACES[to.face].n, w = tileWorld(to.face, to.i, to.j);
    const col = ITEM_COL[type] || ITEM_COL[CRYSTAL];
    for (let k = 0; k < 3; k++)
      emit(w[0] + n[0] * 0.9, w[1] + n[1] * 0.9, w[2] + n[2] * 0.9,
           n[0] * 1.1 + (Math.random() - 0.5) * 1.5,
           n[1] * 1.1 + (Math.random() - 0.5) * 1.5,
           n[2] * 1.1 + (Math.random() - 0.5) * 1.5,
           col.r, col.g, col.b, -0.035, 3.1);
  }
  if (dst.t === HUB) {
    bank(type);
    dst.pulse = 1;
    sfxSold(type);
    if (to) {
      // a small burst in the item's own colour: you can tell from across the
      // worldlet WHAT just sold, not merely that something did
      const n = FACES[to.face].n, w = tileWorld(to.face, to.i, to.j);
      const col = ITEM_COL[type] || ITEM_COL[CRYSTAL];
      for (let k = 0; k < 5; k++)
        emit(w[0] + n[0] * 1.2, w[1] + n[1] * 1.2, w[2] + n[2] * 1.2,
             n[0] * 2.2 + (Math.random() - 0.5) * 2.4,
             n[1] * 2.2 + (Math.random() - 0.5) * 2.4,
             n[2] * 2.2 + (Math.random() - 0.5) * 2.4,
             col.r, col.g, col.b, -0.05, 2.6);
    }
  }
  else if (dst.t === SMELTER) { dst.buf++; dst.bt = type; }
  else if (dst.t === FORGE) { if (dst.fa === 0) dst.fa = type; else dst.fb = type; }
  else if (dst.t === RIFT) { if (--dst.dbt <= 0) riftSettle(dst, true); }
  else dst.item = type;
}

function step() {
  // Smelters run FIRST so a finished ingot leaves before the belts feeding
  // this smelter get their turn — otherwise a full input belt would block the
  // machine that is about to free it, and lines deadlock at exactly the
  // moment they start working.
  eachTile((c, f, i, j) => {
    if (c.t !== SMELTER && c.t !== FORGE) return;
    if (c.cook > 0) {
      c.cook--;
      if (c.cook === 0) {
        const out = c.t === FORGE ? ALLOY : (INGOT_OF[c.bt] || INGOT);
        const dst = cellOf(stepTile(f, i, j, c.d));
        if (dst && dst.t === HUB) bank(out);
        else if (dst && dst.t === BELT && !dst.item) dst.item = out;
        else c.cook = 1;                  // output blocked: hold it, retry
      }
    }
    if (c.t === SMELTER) {
      if (c.cook === 0 && c.buf >= SMELT_IN) { c.buf -= SMELT_IN; c.cook = SMELT_TICKS; }
    } else if (c.cook === 0 && c.fa && c.fb) {
      c.fa = 0; c.fb = 0; c.cook = FORGE_TICKS;
    }
    // THE HEAT COMES UP. A door that snaps between two colours reads as a
    // status LED; one that swells and falls reads as a fire in there.
    const lamp = c.t === SMELTER && c.build && c.build.getObjectByName('lamp');
    if (lamp) {
      c.glow = c.glow || 0;
      c.glow += ((c.cook > 0 ? 1 : 0) - c.glow) * 0.25;
      lamp.material.color.setRGB(0.10 + 0.90 * c.glow,
                                 0.06 + 0.63 * c.glow,
                                 0.22 + 0.07 * c.glow);
    }
  });

  // Collect first, THEN commit. Moving in place would let one item ride the
  // whole line in a single tick depending on iteration order.
  const moves = [];
  eachTile((c, f, i, j) => {
    // A SPLITTER IS A BELT THAT CHOOSES. It sends each item out of a
    // different side in turn, so one miner can feed two smelters without
    // the player hand-balancing anything. The round-robin cursor advances
    // only when an item actually LEAVES — advancing on a failed attempt
    // would silently starve whichever output happened to be busy.
    if (c.t === SPLITTER && c.item) {
      for (let k = 0; k < 4; k++) {
        const dir = (c.rr + k) % 4;
        const to = stepTile(f, i, j, dir);
        if (!to || !accepts(cellOf(to), c.item)) continue;
        moves.push([c, 'to', to]);
        c.rr = (dir + 1) % 4;
        break;
      }
      return;
    }
    // A FILTER IS A BELT THAT SORTS. Matching ore carries straight on;
    // anything else leaves out of the side. Crucially it does NOT fall back to
    // the other output when the chosen one is full — an item that took the
    // wrong exit because the right one was busy is a filter that silently
    // stops filtering, and the player would have no way to see it happen.
    if (c.t === FILTER && c.item) {
      const dir = c.item === c.filt ? c.d : (c.d + 1) % 4;
      const to = stepTile(f, i, j, dir);
      const dst = cellOf(to);
      if (!dst) return;
      if (dst.t === HUB) moves.push([c, 'bank']);
      else if (accepts(dst, c.item)) moves.push([c, 'to', to]);
      return;
    }
    if (c.t !== BELT || !c.item) return;
    const to = stepTile(f, i, j, c.d);
    const dst = cellOf(to);
    if (!dst) return;
    if (dst.t === HUB) moves.push([c, 'bank']);
    // a smelter only accepts CRYSTALS, and only while it has room. An ingot
    // arriving at a smelter simply waits, which is the correct answer and
    // also a visible one — the belt backs up and you can see the mistake.
    else if (accepts(dst, c.item)) moves.push([c, 'to', to]);
  });
  // ── TWO BELTS INTO ONE (2026-09-08) ───────────────────────────────────
  // Acceptance was decided while COLLECTING, against the state at the start of
  // the tick, and the commit trusted it. Two belts feeding the same tile both
  // passed, and the second deliver overwrote the first: a merge silently
  // DESTROYED one item every tick. In a game about throughput that is the
  // worst shape a bug can take — the line looks correct and the number is just
  // quietly lower than it should be, which reads as the game being balanced
  // that way.
  //
  // Re-checking at commit stops the loss. Rotating who goes first stops the
  // unfairness that would replace it: otherwise the winner is whoever eachTile
  // reached first, which is fixed by grid order, so one input starves forever.
  const byDst = new Map();
  for (const mv of moves) {
    if (mv[1] === 'bank') continue;
    const d = cellOf(mv[2]);
    const g = byDst.get(d);
    if (g) g.push(mv); else byDst.set(d, [mv]);
  }
  for (const [d, g] of byDst) {
    if (g.length < 2) continue;
    const k = (d.mrr | 0) % g.length;
    g.push(...g.splice(0, k));            // rotate: a different input leads
    d.mrr = (k + 1) % g.length;
  }
  const order = moves.filter(mv => mv[1] === 'bank');
  for (const g of byDst.values()) order.push(...g);
  for (const mv of order) {
    const c = mv[0];
    if (!c.item) continue;
    if (mv[1] === 'bank') { bank(c.item); c.item = 0; continue; }
    const dst = cellOf(mv[2]);
    if (!accepts(dst, c.item)) continue;   // another input reached it first
    deliver(dst, mv[2], c.item);
    c.item = 0;
  }
  // a rift pays out the ore it lent one tile at a time, like a miner, so the
  // loan arrives on your belts instead of appearing in a counter
  eachTile((c, f, i, j) => {
    if (c.t !== RIFT || c.emit <= 0) return;
    const to = stepTile(f, i, j, c.d);
    const dst = cellOf(to);
    if (accepts(dst, c.dmin)) { deliver(dst, to, c.dmin); c.emit--; }
  });
  eachTile((c, f, i, j) => {
    if (c.t !== MINER) return;
    // a miner digs whatever the seam under it is, which is the face's mineral
    const m = c.min || MINERAL_OF_FACE[f];
    const to = stepTile(f, i, j, c.d);
    const dst = cellOf(to);
    // PROBABILISTIC, NOT A COUNTDOWN. A seam at 40% yields on 40% of ticks,
    // which reads as a line that has slowed rather than a line that stops and
    // starts — and it needs no extra state to do it.
    if (accepts(dst, m) && Math.random() < Math.max(SEAM_FLOOR, c.rich)) {
      deliver(dst, to, m);
      c.rich = Math.max(0, c.rich - SEAM_COST);
      // the seam flexes as the crystal leaves it: which rigs are actually
      // producing is readable from across the face
      if (c.mesh) c.mesh.userData.pulse = 1;
    }
  });
}

// A JAM SHOULD LOOK LIKE A JAM. The tread scrolls whether or not anything is
// moving over it, so a backed-up line was indistinguishable from a running one
// until you noticed the crystals had stopped. Belts holding something that
// cannot advance go amber. Once a tick, not once a frame: it changes at tick
// rate and nothing is gained by asking sixty times a second.
function paintBeltLoad() {
  const n = BELT_KIND.map(() => 0);
  eachTile((c, f, i, j) => {
    if (c.t !== BELT) return;
    const k = beltShape(f, i, j, c);
    if (n[k] >= MAX_BELTS) return;
    const stuck = c.item && !accepts(cellOf(stepTile(f, i, j, c.d)), c.item);
    const dk = beltDecks[k];
    if (stuck) dk.instanceColor.setXYZ(n[k], 1.5, 0.62, 0.3);
    else dk.instanceColor.setXYZ(n[k], 1, 1, 1);
    n[k]++;
  });
  for (const dk of beltDecks) dk.instanceColor.needsUpdate = true;
}

// Items are drawn BETWEEN their tile and the next, so the motion reads smooth
// even though the simulation is a discrete grid step. A blocked item sits
// still, which is what makes a jam legible.
function drawItems(alpha) {
  let n = 0;
  const spin = performance.now() * 0.002;
  eachTile((c, f, i, j) => {
    if (n >= MAX_ITEMS || !c.item) return;
    if (c.t !== BELT && c.t !== FILTER && c.t !== SPLITTER) return;
    // A splitter's next hop is not decided until the tick, and a filter's
    // depends on what it is holding. Items on a splitter therefore sit in the
    // middle of the tile — before this they were not drawn at all, so a
    // backed-up splitter looked empty.
    const dir = c.t === SPLITTER ? c.d
      : c.t === FILTER ? (c.item === c.filt ? c.d : (c.d + 1) % 4)
      : c.d;
    const to = c.t === SPLITTER ? null : stepTile(f, i, j, dir);
    const ahead = cellOf(to);
    // ANYTHING THAT WILL TAKE IT IS MOVEMENT. This listed the destinations by
    // hand and left the machines out, so a crystal about to be smelted sat
    // dead still on the last belt tile and then vanished. accepts() already
    // knows the answer, and it is the same answer the tick will act on.
    const free = ahead && accepts(ahead, c.item);
    const a = free ? alpha : 0;
    // Interpolating between the two tiles' world centres carries an item
    // around an edge on its own: across a corner the two centres are on
    // different faces, so the crystal cuts the corner instead of flying off
    // into space. That the tiles are never more than one diagonal apart is
    // one of the properties the cube-grid test pins down.
    const A = tileWorld(f, i, j), nrm = FACES[f].n;
    const B = ahead ? tileWorld(to.face, to.i, to.j) : A;
    // DERIVED FROM THE TILE, NOT FROM THE ITEM. A per-item random would make
    // a crystal jump sideways every time it advanced; keyed to the tile it is
    // standing on, the whole line looks hand-placed and nothing twitches.
    const key = (f * 73856093) ^ (i * 19349663) ^ (j * 83492791);
    const jit = ((key >>> 8) & 1023) / 1023 - 0.5;
    const ph = ((key >>> 18) & 1023) / 1023 * 6.283;
    const side = FACES[f].v;
    // a shallow carry bob, so a run of items has a wave in it rather than
    // sliding like a decal
    const lift = 0.42 + Math.sin(a * Math.PI) * 0.045;
    const off = jit * T * 0.10;
    _p.set(A[0] + (B[0] - A[0]) * a + nrm[0] * lift + side[0] * off,
           A[1] + (B[1] - A[1]) * a + nrm[1] * lift + side[1] * off,
           A[2] + (B[2] - A[2]) * a + nrm[2] * lift + side[2] * off);
    _up.set(nrm[0], nrm[1], nrm[2]);
    _q.setFromAxisAngle(_up, spin + ph);
    _m.compose(_p, _q, _s);
    items.setColorAt(n, ITEM_COL[c.item] || ITEM_COL[CRYSTAL]);
    items.setMatrixAt(n++, _m);
  });
  items.count = n;
  items.instanceMatrix.needsUpdate = true;
  if (items.instanceColor) items.instanceColor.needsUpdate = true;
  return n;
}

// ── input: raycast the ground plane, drag to draw belts ────────────────────
const ray = new THREE.Raycaster();
const ndc = new THREE.Vector2();
const hitPt = new THREE.Vector3();

/** The tile a world point sits over, or null if it is off the cube. */
function tileOfPoint(p) {
  const face = faceOfPoint(p.x, p.y, p.z), f = FACES[face];
  const a = p.x * f.u[0] + p.y * f.u[1] + p.z * f.u[2];
  const b = p.x * f.v[0] + p.y * f.v[1] + p.z * f.v[2];
  const i = Math.floor(a / T + N / 2), j = Math.floor(b / T + N / 2);
  if (i < 0 || j < 0 || i >= N || j >= N) return null;
  return { face, i, j };
}
let tool = 'miner';
let drawing = false;
let lastCell = null;

// In first person you aim with the CROSSHAIR, not the cursor — the pointer is
// locked and has no position. Overhead keeps the cursor. Reach is limited on
// foot for the obvious reason: a build game where you can place a machine on
// the far side of the island from where you stand is a board game again.
function cellUnder(ev) {
  if (overhead && ev) {
    ndc.set((ev.clientX / innerWidth) * 2 - 1, -(ev.clientY / innerHeight) * 2 + 1);
  } else {
    ndc.set(0, 0);
  }
  ray.setFromCamera(ndc, camera);
  // AIM AT THE SOLID, NOT AT A PLANE. The ground used to be the y=0 plane,
  // which on a cube would let you place machines on a face you are standing
  // inside of. Raycasting the cube itself means you build on the surface you
  // are actually looking at, whichever of the six it is.
  const hit = ray.intersectObject(cube, false)[0];
  if (!hit) return null;
  hitPt.copy(hit.point);
  if (!overhead && hitPt.distanceTo(camera.position) > REACH) return null;
  return tileOfPoint(hitPt);
}

// the ghost: what you are about to build, where you are about to build it
const ghost = new THREE.Mesh(
  new THREE.BoxGeometry(T * 0.92, 0.5, T * 0.92),
  new THREE.MeshBasicMaterial({ color: 0x6cf5d0, transparent: true, opacity: 0.28,
    depthWrite: false }));
ghost.visible = false;
scene.add(ghost);
const ghostEdge = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.BoxGeometry(T * 0.92, 0.5, T * 0.92)),
  new THREE.LineBasicMaterial({ color: 0x9dffe8, transparent: true, opacity: 0.85 }));
ghost.add(ghostEdge);

function updateGhost() {
  const t = cellUnder(null);
  if (!t) { ghost.visible = false; return; }
  const c = cellOf(t);
  const legal = tool === 'erase' ? (c.t !== EMPTY && c.t !== NODE)
    : tool === 'miner' ? c.t === NODE
    : c.t !== NODE;
  ghost.visible = true;
  seat(ghost, t.face, t.i, t.j, 0, 0.26);
  ghost.material.color.setHex(legal ? 0x6cf5d0 : 0xff6b7d);
  ghostEdge.material.color.setHex(legal ? 0x9dffe8 : 0xffa8b4);
}

// WHICH WAY DID THE DRAG GO. On a flat grid this was a subtraction of indices.
// Across an edge the two tiles are not in the same coordinate system at all,
// so the question is asked the only way that stays true: try each of the four
// headings and see which one actually steps from a to b.
function dirBetween(a, b) {
  for (let d = 0; d < 4; d++) {
    const s = stepTile(a.face, a.i, a.j, d);
    if (s && s.face === b.face && s.i === b.i && s.j === b.j) return d;
  }
  return null;
}

function apply(t, dir) {
  if (!UNLOCKED[tool]) return;      // hotkeys and drags go through here too
  const d = dir == null ? 0 : dir;
  if (tool === 'erase') { removeAt(t.face, t.i, t.j); return; }
  if (tool === 'miner') { place(t.face, t.i, t.j, MINER, d); return; }
  if (tool === 'hub') { place(t.face, t.i, t.j, HUB, 0); return; }
  if (tool === 'smelter') { place(t.face, t.i, t.j, SMELTER, d); return; }
  if (tool === 'splitter') { place(t.face, t.i, t.j, SPLITTER, 0); return; }
  if (tool === 'forge') { place(t.face, t.i, t.j, FORGE, d); return; }
  if (tool === 'filter') { place(t.face, t.i, t.j, FILTER, d); return; }
  if (tool === 'rift') { place(t.face, t.i, t.j, RIFT, d); return; }
  if (tool === 'belt') { place(t.face, t.i, t.j, BELT, d); }
}

renderer.domElement.addEventListener('pointerdown', e => {
  if (e.button !== 0) return;
  // INSPECTING IS LOOKING, NOT BUILDING (2026-09-07). The studio arms Inspect
  // to let someone click things and read what they are; with the build path
  // still live, every one of those clicks dropped a machine on the world they
  // were trying to examine.
  if (inspectOn) return;
  const c = cellUnder(e);
  if (!c) return;
  drawing = true;
  lastCell = c;
  apply(c, null);
});
renderer.domElement.addEventListener('pointermove', e => {
  if (inspectOn || !drawing || !lastCell) return;
  const c = cellUnder(e);
  if (!c || (c.face === lastCell.face && c.i === lastCell.i && c.j === lastCell.j)) return;
  const d = dirBetween(lastCell, c);
  if (d == null) { lastCell = c; return; }
  // the tile we just left now points at the one we moved to
  const prev = cellOf(lastCell);
  if (prev.t === BELT || prev.t === MINER) {
    prev.d = d;
    if (prev.t === BELT) beltsDirty = true;
    else if (prev.build) seat(prev.build, lastCell.face, lastCell.i, lastCell.j, d, 0);
  }
  // the drag arrives on the new tile heading the same way it left the old one,
  // which across an edge is NOT the direction the mouse moved
  const sd = stepTile(lastCell.face, lastCell.i, lastCell.j, d);
  apply(c, sd ? sd.d : d);
  lastCell = c;
});
addEventListener('pointerup', () => { drawing = false; lastCell = null; });

// Point at a filter and press F. A short cycle rather than a text box: the
// same decision space as a script, with nothing to parse, nothing to corrupt a
// shared save, and no typing in a first-person game.
function cycleFilter() {
  const t = cellUnder(null);
  if (!t) return;
  const c = cellOf(t);
  if (c.t !== FILTER) return;
  const k = MINERALS.indexOf(c.filt);
  c.filt = MINERALS[(k + 1) % MINERALS.length];
  const gate = c.build && c.build.getObjectByName('gate');
  if (gate) {
    gate.material.color.setHex(MIN_COL[c.filt]);
    gate.material.emissive.setHex(MIN_COL[c.filt]);
  }
}

function pickTool(name) {
  if (typeof setHolo === 'function' && UNLOCKED[name]) setHolo(name);
  if (!UNLOCKED[name]) {
    // say WHY, rather than ignoring the click. A control that does nothing and
    // explains nothing is indistinguishable from a broken one.
    const el = document.querySelector('.tool[data-tool="' + name + '"]');
    if (el) { el.classList.add('deny'); setTimeout(() => el.classList.remove('deny'), 320); }
    const t = document.getElementById('toast');
    if (t && goalIdx < GOALS.length) {
      t.textContent = 'locked — ' + GOALS[goalIdx].text;
      t.classList.add('on'); toastAt = 2.2;
    }
    return;
  }
  tool = name;
  document.querySelectorAll('.tool').forEach(o =>
    o.classList.toggle('on', o.dataset.tool === name));
}
document.querySelectorAll('.tool').forEach(el => {
  el.addEventListener('pointerdown', ev => { ev.stopPropagation(); pickTool(el.dataset.tool); });
});
addEventListener('keydown', e => {
  const k = { '1': 'miner', '2': 'belt', '3': 'smelter', '4': 'splitter',
              '5': 'hub', '6': 'forge', '7': 'filter', '8': 'rift',
              '9': 'erase' }[e.key];
  if (k) pickTool(k);
  if (e.code === 'KeyF') cycleFilter();
  if (e.code === 'KeyM') audioMute(!AUDIO.muted);
  const u = { 'KeyZ': 'tick', 'KeyX': 'yield', 'KeyC': 'smelt' }[e.code];
  if (u) buy(u);
});

// ── YOU ARE ON THE ISLAND ───────────────────────────────────────────────────
// Arranging a factory on a board and STANDING IN ONE are different games. The
// second is the one people lose evenings to, because a belt you walked beside
// is yours in a way a belt you dragged on a grid is not. First person is the
// default; the overhead view stays on Tab because routing a junction from eye
// level is genuinely worse than seeing it from above, and a build game needs
// both.
const EYE = 1.68, REACH = 12;
const player = {
  pos: new THREE.Vector3(0, HALF + EYE, 0),
  face: 0,
  // The heading is a WORLD vector tangent to the current face, not a yaw
  // angle. A yaw needs a reference direction per face, and the six of them
  // cannot be made to agree along every edge — one seam always ends up with
  // the player spinning as they cross it.
  fwd: new THREE.Vector3(0, 0, -1),
  up: new THREE.Vector3(0, 1, 0),
  h: 0, vy: 0,
  // starts looking DOWN at the ground. Level-eyed, the surface is metres
  // beyond arm's reach and the build ghost simply never appears — you would
  // be standing in a build game with no way to tell why nothing can be placed.
  pitch: -0.38, onGround: true,
};
// the camera's up lags the player's by a few frames, so crossing an edge
// ROLLS the world over instead of snapping it. This is the shot the whole
// mechanic exists for; a hard cut throws it away.
const camUp = new THREE.Vector3(0, 1, 0);
let overhead = false;
// FRAMED FOR A CUBE, NOT A SLAB (2026-09-07). A fixed 46m orbit was outside a
// flat island and INSIDE a worldlet — Tab showed you a dark field of grid
// lines and nothing else. Every distance here is a multiple of the world.
let orbYaw = 0.72, orbPitch = 0.62, orbDist = HALF * 4.4;

const keys = Object.create(null);
addEventListener('keydown', e => {
  keys[e.code] = true;
  if (e.code === 'Tab') { e.preventDefault(); overhead = !overhead; }
});
addEventListener('keyup', e => { keys[e.code] = false; });
addEventListener('contextmenu', e => e.preventDefault());

// pointer lock is what makes it feel embodied rather than operated
renderer.domElement.addEventListener('click', () => {
  audioStart();                       // the browser wants a gesture; this is it
  if (!overhead && document.pointerLockElement !== renderer.domElement) {
    renderer.domElement.requestPointerLock();
  }
});
addEventListener('mousemove', e => {
  if (document.pointerLockElement !== renderer.domElement) return;
  // turning is a rotation about whichever way is up HERE
  player.fwd.applyAxisAngle(player.up, -e.movementX * 0.0022).normalize();
  player.pitch = Math.max(-1.45, Math.min(1.35, player.pitch - e.movementY * 0.0022));
});
addEventListener('wheel', e => {
  if (overhead) orbDist = Math.max(HALF * 1.5, Math.min(HALF * 6, orbDist * (1 + Math.sign(e.deltaY) * 0.09)));
}, { passive: true });
addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  sizePost();          // the targets are not attached to the canvas by magic
});

// Belts and filters are ankle-high and you walk over them; everything else on
// the grid is something you walk around. An ore seam counts — it is a metre of
// crystal standing out of the ground, and phasing through one looked worse
// than phasing through a machine.
const SOLID_T = { 1: 1, 3: 1, 4: 1, 5: 1, 6: 1, 7: 1, 9: 1 };
const PLAYER_R = 0.4;

/** Is the player's circle, at face-local (a,b), overlapping a solid tile? */
function solidAt(face, a, b) {
  const lo = PLAYER_R + T / 2;
  const ci = Math.floor(a / T + N / 2), cj = Math.floor(b / T + N / 2);
  for (let i = ci - 1; i <= ci + 1; i++) {
    for (let j = cj - 1; j <= cj + 1; j++) {
      if (i < 0 || j < 0 || i >= N || j >= N) continue;   // an edge is not a wall
      if (!SOLID_T[cells[face][i][j].t]) continue;
      const cx = (i + 0.5 - N / 2) * T, cz = (j + 0.5 - N / 2) * T;
      if (Math.abs(a - cx) < lo && Math.abs(b - cz) < lo) return true;
    }
  }
  return false;
}

const _rt = new THREE.Vector3(), _wish = new THREE.Vector3();
let bobPhase = 0, bobAmt = 0, moveMag = 0;
const _n3 = new THREE.Vector3(), _oldN = new THREE.Vector3();
const _qr = new THREE.Quaternion();
const faceNormal = (face, out) => {
  const n = FACES[face].n; return out.set(n[0], n[1], n[2]);
};

function movePlayer(dt) {
  faceNormal(player.face, _n3);
  player.up.copy(_n3);
  // keep the heading tangent to the face actually underfoot
  player.fwd.addScaledVector(_n3, -player.fwd.dot(_n3));
  if (player.fwd.lengthSq() < 1e-8) {
    const u = FACES[player.face].u; player.fwd.set(u[0], u[1], u[2]);
  }
  player.fwd.normalize();
  _rt.crossVectors(player.fwd, _n3).normalize();

  _wish.set(0, 0, 0);
  if (keys['KeyW']) _wish.add(player.fwd);
  if (keys['KeyS']) _wish.sub(player.fwd);
  if (keys['KeyD']) _wish.add(_rt);
  if (keys['KeyA']) _wish.sub(_rt);
  moveMag = _wish.length();
  if (_wish.lengthSq() > 0) _wish.normalize();
  const speed = keys['ShiftLeft'] ? 11 : 6.2;

  // gravity points at the face you are on, so "down" is a different world
  // direction depending on where you are standing
  if (keys['Space'] && player.onGround) { player.vy = 6.4; player.onGround = false; }
  player.vy -= 19 * dt;
  player.h += player.vy * dt;
  if (player.h <= 0) { player.h = 0; player.vy = 0; player.onGround = true; }

  // ── WALKING INTO THINGS (2026-09-08) ──────────────────────────────────
  // You could walk through your own factory, which reads as the machines not
  // being there. Resolved in FACE-LOCAL coordinates rather than world ones:
  // on the underside of the cube "x" and "z" mean nothing, but the face's own
  // u and v axes always mean along-the-tiles.
  //
  // Each axis is tried on its own so a shoulder against a smelter slides along
  // it instead of stopping dead — a factory is a corridor maze and stopping
  // dead in one is miserable.
  const fc = FACES[player.face];
  let pa = player.pos.x * fc.u[0] + player.pos.y * fc.u[1] + player.pos.z * fc.u[2];
  let pb = player.pos.x * fc.v[0] + player.pos.y * fc.v[1] + player.pos.z * fc.v[2];
  const da = (_wish.x * fc.u[0] + _wish.y * fc.u[1] + _wish.z * fc.u[2]) * speed * dt;
  const db = (_wish.x * fc.v[0] + _wish.y * fc.v[1] + _wish.z * fc.v[2]) * speed * dt;
  // If you are ALREADY inside something — a machine placed on top of you, a
  // save restored under a smelter — collision is skipped entirely this frame.
  // A player who cannot move is a bug report; a player who can walk out of a
  // wall is a shrug.
  const stuck = solidAt(player.face, pa, pb);
  if (!stuck) {
    if (!solidAt(player.face, pa + da, pb)) pa += da;
    if (!solidAt(player.face, pa, pb + db)) pb += db;
  } else { pa += da; pb += db; }
  const ph = HALF + EYE + player.h;
  player.pos.set(fc.n[0] * ph + fc.u[0] * pa + fc.v[0] * pb,
                 fc.n[1] * ph + fc.u[1] * pa + fc.v[1] * pb,
                 fc.n[2] * ph + fc.u[2] * pa + fc.v[2] * pb);

  // WALKING OFF AN EDGE. Two passes, because a corner crosses two edges in a
  // single frame at a run. The heading is carried across by the rotation that
  // takes the old normal onto the new one — a projection cannot do it: walk
  // straight off an edge and your forward direction IS the new face's normal,
  // which projects to nothing.
  for (let pass = 0; pass < 2; pass++) {
    const f = FACES[player.face];
    const a = player.pos.dot(_rt.set(f.u[0], f.u[1], f.u[2]));
    const b = player.pos.dot(_rt.set(f.v[0], f.v[1], f.v[2]));
    let over = null;
    if (a > HALF) over = f.u;
    else if (a < -HALF) over = _ng(f.u);
    else if (b > HALF) over = f.v;
    else if (b < -HALF) over = _ng(f.v);
    if (!over) break;
    let nf = -1;
    for (let k = 0; k < 6; k++) if (_eqv(FACES[k].n, over)) { nf = k; break; }
    if (nf < 0) break;
    _oldN.copy(player.up);
    faceNormal(nf, _n3);
    _qr.setFromUnitVectors(_oldN, _n3);
    player.fwd.applyQuaternion(_qr).normalize();
    player.face = nf;
    player.up.copy(_n3);
    player.h = 0; player.vy = 0; player.onGround = true;
    // RE-SEAT IMMEDIATELY, not after the loop (2026-09-07). Left until the
    // end, the second pass read a position that was still measured against
    // the OLD face: standing eye-height above the top face reads as 1.68m
    // off the side face's edge, so the player crossed straight back and the
    // net effect was a wall you could not walk over. The two passes exist for
    // corners; they only mean anything once each one lands.
    seatPlayer();
  }
  seatPlayer();
}

// Sit exactly eye-height (plus any jump) above the current face, inside its
// square. This is the only place the player's world position is written from
// face coordinates, which is why crossing an edge is a change of two numbers
// rather than a special case for each of the twelve edges.
function seatPlayer() {
  const f = FACES[player.face];
  const lim = HALF - 0.05;
  const a = Math.max(-lim, Math.min(lim,
    player.pos.x * f.u[0] + player.pos.y * f.u[1] + player.pos.z * f.u[2]));
  const b = Math.max(-lim, Math.min(lim,
    player.pos.x * f.v[0] + player.pos.y * f.v[1] + player.pos.z * f.v[2]));
  const up = HALF + EYE + player.h;
  player.pos.set(f.n[0] * up + f.u[0] * a + f.v[0] * b,
                 f.n[1] * up + f.u[1] * a + f.v[1] * b,
                 f.n[2] * up + f.u[2] * a + f.v[2] * b);
}

// ── a starter line, so the loop is legible the moment it loads ─────────────
// Called again after every meltdown: a prestige that drops you onto an empty
// cube with no line running is indistinguishable from having lost.
function seedLine(placePlayer) {
  // Pick a node with a CLEAR run east of it. The first version just took the
  // first node it found and drew six tiles east regardless — a second node
  // sitting in that line silently refused two placements, so the demo line
  // ended in mid-air with no hub and delivered nothing. A starter line that
  // does not complete the loop teaches the player the wrong thing.
  // On the top face, so the game opens on the orientation people expect —
  // the other five are discovered by walking there.
  const RUN = 6, F = 0;
  let found = null;
  for (let i = 2; i < N - RUN - 1 && !found; i++) {
    for (let j = 2; j < N - 2 && !found; j++) {
      if (cells[F][i][j].t !== NODE) continue;
      let clear = true;
      for (let k = 1; k <= RUN && clear; k++) clear = cells[F][i + k][j].t === EMPTY;
      if (clear) found = [i, j];
    }
  }
  if (!found) return;
  const x = found[0], z = found[1];
  place(F, x, z, MINER, 0);
  place(F, x + 1, z, BELT, 0);
  place(F, x + 2, z, BELT, 0);
  place(F, x + 3, z, SMELTER, 0);     // two crystals in, one ingot out
  place(F, x + 4, z, BELT, 0);
  place(F, x + 5, z, BELT, 0);
  place(F, x + RUN, z, HUB, 0);

  // STAND WHERE THE LOOP IS (2026-09-07). A fixed spawn on the south edge left
  // the whole starter line behind the player on a large grid: the game was
  // running perfectly and the first frame showed bare ground. Put the camera
  // just south of the middle of the line, looking along it, so the first thing
  // anyone sees — player or screenshot gate — is ore actually moving.
  // BEHIND the line, not past the edge. The top face's v axis is -Z, so the
  // tile "in front of" the player is j+1; standing at j+4 put the spawn four
  // tiles PAST the line and, on a line near the far edge, off the face
  // entirely — where the clamp pinned it and W did nothing at all.
  const w = tileWorld(F, x + RUN / 2, Math.max(1, Math.min(N - 2, z - 4)));
  player.pos.set(w[0], HALF + EYE, w[2]);
  player.face = F;
  player.up.set(0, 1, 0);
  camUp.set(0, 1, 0);
  // FACES[0].v is -Z, so the line we just built lies that way
  if (!placePlayer) return;
  player.fwd.set(0, 0, -1);
}
seedLine(true);

// ── THE CHRONOS RIFT ───────────────────────────────────────────────────────
// A rift lends you ore and names its price on the HUD: this much of THAT ore,
// back through the same ring, before the clock runs out. Pay and it settles at
// triple the market rate. Miss and it throws every machine near it into the
// sky — the meltdown's debris path, aimed at you rather than chosen by you.
//
// The borrowed ore is deliberately whichever one the market currently pays
// most for, so a rift is a bet on a price you can see moving, and the filter
// tile is how you route the repayment back without unpicking your line.
const RIFT_COUNT = 6;        // ore lent per opening
const RIFT_WINDOW = 45;      // seconds to pay it back
const RIFT_COOL = 22;        // seconds shut afterwards
const RIFT_BLAST = 3;        // tiles of factory it takes when it is not paid

function riftOpen(c) {
  // borrow against the best price on the board
  let best = MINERALS[0];
  for (const m of MINERALS) if (PRICE[INGOT_OF[m]] > PRICE[INGOT_OF[best]]) best = m;
  c.dmin = best;
  c.dbt = RIFT_COUNT;
  c.emit = RIFT_COUNT;
  c.left = RIFT_WINDOW;
  c.cool = 0;
}

function riftSettle(c, paid) {
  if (paid) {
    const v = (VALUE[INGOT_OF[c.dmin]] || 6) * (PRICE[INGOT_OF[c.dmin]] || 1)
              * RIFT_COUNT * 0.5;
    ore += v; runValue += v;
  }
  c.dbt = 0; c.emit = 0; c.left = 0; c.dmin = 0;
  c.cool = RIFT_COOL;
}

// The storm. Everything within RIFT_BLAST tiles ON THE SAME FACE is thrown —
// same face because a blast that reached around an edge would be impossible to
// read, and the player has to be able to see what they are risking.
function riftStorm(f, i, j) {
  beltsDirty = true;
  for (let a = Math.max(0, i - RIFT_BLAST); a <= Math.min(N - 1, i + RIFT_BLAST); a++) {
    for (let b = Math.max(0, j - RIFT_BLAST); b <= Math.min(N - 1, j + RIFT_BLAST); b++) {
      const c = cells[f][a][b];
      if (c.t === EMPTY || c.t === NODE || c.t === RIFT) continue;
      const piece = pieceFor(f, a, b, c);
      if (piece) { throwPiece(piece); c.build = null; }
      c.t = c.mesh ? NODE : EMPTY;
      c.item = 0; c.buf = 0; c.bt = 0; c.fa = 0; c.fb = 0; c.cook = 0;
    }
  }
  melting = Math.max(melting, 1.2);
  refreshCounts();
}

function stepRifts(dt) {
  eachTile((c, f, i, j) => {
    if (c.t !== RIFT) return;
    if (c.cool > 0) {
      c.cool -= dt;
      if (c.cool <= 0) riftOpen(c);
    } else if (c.left > 0) {
      // THE CLOCK STARTS WHEN THE LOAN LANDS (2026-09-07). Counting down while
      // the rift still had ore to pay out meant a rift with a blocked output
      // demanded repayment of something it had never handed over, and then
      // blew up the factory for not returning it.
      if (c.emit === 0) c.left -= dt;
      if (c.left <= 0) { riftStorm(f, i, j); riftSettle(c, false); }
    } else if (c.dbt === 0 && c.emit === 0) {
      riftOpen(c);                     // a freshly placed rift opens at once
    }
    const lamp = c.build && c.build.getObjectByName('lamp');
    if (lamp) lamp.material.color.setHex(
      c.dbt > 0 ? (MIN_COL[c.dmin] || 0xff5ad9) : 0x2a2050);
    const ring = c.build && c.build.getObjectByName('ring');
    if (ring) ring.rotation.z += dt * (c.dbt > 0 ? 2.4 : 0.4);
  });
}

// ── the meltdown itself ────────────────────────────────────────────────────
// The machines are not deleted, they are THROWN. Every build group is detached
// from its tile, given an outward velocity off the cube and a tumble, and left
// to shrink into nothing over a couple of seconds. The engine side of this
// project has shipped physics-driven destruction before; here it is two lines
// of integration per frame, and it is the only moment in the game that is
// worth filming.
const debris = [];
let melting = 0;

// ONE PLACE THAT THROWS A MACHINE. The meltdown chooses to do this and the
// rift storm does it to you, and the two looking different would read as a
// bug rather than as two causes of the same event.
function throwPiece(g) {
  const p = g.position;
  const r = Math.max(1e-3, Math.hypot(p.x, p.y, p.z));
  debris.push({
    o: g,
    // SLOW ENOUGH TO WATCH (2026-09-07). The first pass threw everything at
    // 9-25 m/s and the entire factory was out of frame inside 300ms — the one
    // moment in the game worth filming, over before a screenshot could catch
    // it. Pieces arc out and fall back toward the cube.
    v: new THREE.Vector3(
      p.x / r * (5 + Math.random() * 6) + (Math.random() - 0.5) * 4,
      p.y / r * (5 + Math.random() * 6) + (Math.random() - 0.5) * 4,
      p.z / r * (5 + Math.random() * 6) + (Math.random() - 0.5) * 4),
    w: new THREE.Vector3((Math.random() - 0.5) * 9,
                         (Math.random() - 0.5) * 9,
                         (Math.random() - 0.5) * 9),
  });
}

function meltdown() {
  if (ore < MELT_MIN || melting > 0) return;
  const won = Math.max(1, coresFor(runValue));
  cores += won;
  sfxMelt();
  // the most filmable moment in the game, shown from where it can be seen
  playIntro('MELTDOWN', '+' + won + (won === 1 ? ' core' : ' cores') +
            ' \u00b7 the factory is thrown to the sky', 2.6, true);

  eachTile((c, f, i, j) => {
    const piece = pieceFor(f, i, j, c);
    if (piece) {
      throwPiece(piece);
      c.build = null;
    }
    // a node outlives the factory built on it, exactly as it does for ERASE
    c.t = c.mesh ? NODE : EMPTY;
    c.item = 0; c.buf = 0; c.bt = 0; c.fa = 0; c.fb = 0; c.cook = 0; c.rr = 0;
  });

  ore = 0; ingots = 0; runValue = 0;
  beltsDirty = true;
  for (const k in UPGRADES) UPGRADES[k].lvl = 0;
  applyUpgrades();
  renderUpgrades();
  items.count = 0;
  melting = 2.4;
  refreshCounts();
  document.getElementById('tok').textContent = cores;
  renderWorlds();                     // a core may have opened somewhere new
}

function stepDebris(dt) {
  for (let k = debris.length - 1; k >= 0; k--) {
    const d = debris[k];
    // the worldlet still pulls: pieces arc out and come back, which reads as
    // a collapse rather than as a scene being deleted
    const p = d.o.position;
    const r = Math.max(1e-3, Math.hypot(p.x, p.y, p.z));
    d.v.addScaledVector(_bx.set(p.x / r, p.y / r, p.z / r), -7 * dt);
    p.addScaledVector(d.v, dt);
    d.o.rotateX(d.w.x * dt); d.o.rotateY(d.w.y * dt); d.o.rotateZ(d.w.z * dt);
    const sc = Math.max(0, d.o.scale.x - dt * 0.42);
    d.o.scale.setScalar(sc);
    if (sc <= 0.02) { scene.remove(d.o); debris.splice(k, 1); }
  }
}

{
  const btn = document.getElementById('melt');
  if (btn) btn.addEventListener('pointerdown', ev => { ev.stopPropagation(); meltdown(); });
}

// ── WORLDS ─────────────────────────────────────────────────────────────────
// Everything a world changes is scenery: where you are, never how the factory
// behaves. Ore colours are excluded on purpose — they are how a belt is read at
// a glance, and re-learning them per world would be a tax on travelling.
const WORLDS = [
  { id: 'prompt', plate: { base: '#8792c4', tint: '#6a74a6', seam: 'rgba(90,100,150,0.75)', rivet: 'rgba(190,200,235,0.55)', overlay: null }, weather: { col: [0.55, 0.62, 0.80], rate: 5, size: 0.028, fall: 0.25, drift: 0.35, life: 0.16 }, edge: 0x7fd8ff, sun: 0xfff2d6, name: SPEC.title || 'Crystal Isle', cores: 0,
    blurb: 'where the prompt dropped you',
    sky: SKY_COL, fog: FOG_COL, ground: 0x3c4470, grid: 0x46527d, star: 0xffffff },
  { id: 'ember', plate: { base: '#6a5a58', tint: '#4a3a38', seam: 'rgba(40,24,22,0.8)', rivet: 'rgba(160,120,110,0.5)', overlay: 'soot' }, weather: { col: [0.95, 0.42, 0.22], rate: 14, size: 0.040, fall: 0.55, drift: 0.55, life: 0.14 }, edge: 0xff9a5c, sun: 0xffd0a0, name: 'Ember Reach', cores: 2,
    blurb: 'a cinder still cooling',
    sky: 0x1a0c0e, fog: 0x2a1210, ground: 0x6b3a34, grid: 0xa2564a, star: 0xffd2b8 },
  { id: 'frost', plate: { base: '#c4d2e6', tint: '#a8b8cf', seam: 'rgba(120,140,170,0.6)', rivet: 'rgba(255,255,255,0.7)', overlay: 'frost' }, weather: { col: [0.92, 0.96, 1.00], rate: 18, size: 0.034, fall: 0.40, drift: 0.90, life: 0.12 }, edge: 0xcfe8ff, sun: 0xe8f4ff, name: 'Frostline', cores: 5,
    blurb: 'ice over something older',
    sky: 0x0a1420, fog: 0x11202f, ground: 0x7c93ad, grid: 0xa8c4dd, star: 0xdcefff },
  { id: 'verdant', plate: { base: '#7c8a78', tint: '#5f6e5a', seam: 'rgba(50,64,48,0.75)', rivet: 'rgba(170,190,160,0.5)', overlay: 'moss' }, weather: { col: [0.55, 0.95, 0.60], rate: 9, size: 0.046, fall: -0.30, drift: 0.45, life: 0.10 }, edge: 0x8fe6a0, sun: 0xdfffe6, name: 'The Verdant Fault', cores: 9,
    blurb: 'it grew back around the machines',
    sky: 0x08170f, fog: 0x0f2418, ground: 0x3f6b4a, grid: 0x63a072, star: 0xd6ffe0 },
];
let worldIdx = 0;

function applyWorld(k) {
  const w = WORLDS[k] || WORLDS[0];
  worldIdx = WORLDS[k] ? k : 0;
  scene.background.setHex(w.sky);
  worldFog.color.setHex(w.fog);
  cube.material.color.setHex(w.ground);
  gridLines.material.color.setHex(w.grid);
  starField.material.color.setHex(w.star);
  if (cubeEdges) cubeEdges.material.color.setHex(w.edge || w.grid);
  if (sunDisc) sunDisc.material.color.setHex(w.sun || 0xfff2d6);
  // the bounce light is the world's own colour, which is what stops a red
  // planet from having neutral grey machines standing on it
  scene.environment = buildEnv(w.edge || w.grid, w.ground);
  // the plating is rebuilt for the world, not recoloured: frost, moss and
  // soot are things drawn ON it, and a tint cannot draw
  if (cube.material.map) cube.material.map.dispose();
  if (cube.material.roughnessMap) cube.material.roughnessMap.dispose();
  cube.material.map = plateTexture(w.plate);
  cube.material.roughnessMap = plateRoughness(w.plate);
  cube.material.needsUpdate = true;
  // a real vertical gradient: lifted overhead, deeper below, so the void has a
  // top and a bottom instead of being one flat value with a band painted on it
  buildSky(new THREE.Color(w.sky).lerp(new THREE.Color(w.edge || w.grid), 0.16).getHex(),
           new THREE.Color(w.sky).lerp(new THREE.Color(0x000000), 0.55).getHex(),
           w.edge || w.grid);
  matComposite.uniforms.uTint.value.setHex(w.fog);
  const h = document.querySelector('#hud h1');
  if (h) h.textContent = String(w.name).toUpperCase();
  renderWorlds();
}

function renderWorlds() {
  const el = document.getElementById('world');
  if (!el) return;
  let html = '<b>' + WORLDS[worldIdx].name.toUpperCase() + '</b>'
           + '<small>' + WORLDS[worldIdx].blurb + '</small>';
  for (let k = 0; k < WORLDS.length; k++) {
    if (k === worldIdx) continue;
    const w = WORLDS[k], can = cores >= w.cores;
    html += '<div class="wr' + (can ? ' can' : '') + '" data-world="' + k + '">'
         + w.name + '<span>' + (can ? 'travel' : w.cores + ' cores') + '</span></div>';
  }
  el.innerHTML = html;
  el.querySelectorAll('.wr.can').forEach(o => o.addEventListener('pointerdown', ev => {
    ev.stopPropagation();
    travelTo(+o.dataset.world);
  }));
}

// TRAVELLING IS A FRESH FACTORY IN A NEW PLACE. Cores and the goal chain are
// what you carry; the factory and the value are not. Same shape as a meltdown,
// so there is one rule to learn about what survives you starting over.
function travelTo(k) {
  const w = WORLDS[k];
  if (!w || k === worldIdx || cores < w.cores) return;
  playIntro(w.name, w.blurb);          // arriving is the payoff; show the place
  clearFactory();
  ore = 0; ingots = 0; alloys = 0; runValue = 0;
  for (const key in UPGRADES) UPGRADES[key].lvl = 0;
  applyUpgrades(); renderUpgrades();
  applyWorld(k);
  seedLine(true);
  refreshCounts();
  const t = document.getElementById('toast');
  if (t) { t.textContent = w.name.toUpperCase() + ' — ' + w.blurb;
           t.classList.add('on'); toastAt = 3.5; }
  save();
}

// ── PROGRESSION ────────────────────────────────────────────────────────────
// Ordered so each unlock lands when the previous one has made it mean
// something: routing before sorting, and the FORGE only after you have stood
// on a second face and seen that the ore there is a different colour. A player
// who never walks over an edge never learns the thing this game is for, so it
// is a goal rather than a hope.
const visitedFaces = new Set();
const START_TOOLS = ['miner', 'belt', 'smelter', 'hub', 'erase'];
const UNLOCKED = {};
for (const k of START_TOOLS) UNLOCKED[k] = 1;
let goalIdx = 0;

const GOALS = [
  { text: 'bank 40 value', unlock: 'splitter',
    tip: 'the hub buys anything that reaches it',
    got: 'SPLITTER — one line can feed two machines',
    done: () => ore >= 40, progress: () => ore / 40 },
  { text: 'stand on a second face', unlock: 'forge',
    tip: 'walk over an edge; the world turns under you',
    got: 'FORGE — two different ores in, one alloy out',
    done: () => visitedFaces.size >= 2, progress: () => (visitedFaces.size - 1) },
  { text: 'forge one alloy', unlock: 'filter',
    tip: 'no single face grows two ores, so a belt has to cross',
    got: 'FILTER — point at it and press F to sort by ore',
    done: () => alloys >= 1, progress: () => alloys },
  { text: 'bank 250 value', unlock: 'rift',
    tip: 'seams thin as they are worked and grow back — spread the rigs out',
    got: 'CHRONOS RIFT — borrowed ore, on a deadline',
    done: () => ore >= 250, progress: () => ore / 250 },
  { text: 'bank ' + MELT_MIN + ' value', unlock: 'meltdown',
    tip: 'enough of a factory to be worth destroying',
    got: 'MELTDOWN — collapse it all for a permanent core',
    done: () => ore >= MELT_MIN, progress: () => ore / MELT_MIN },
];

function renderGoal() {
  const el = document.getElementById('goal');
  if (el) {
    if (goalIdx >= GOALS.length) {
      el.innerHTML = '<b>ALL SYSTEMS ONLINE</b><small>the worldlet is yours</small>';
    } else {
      const g = GOALS[goalIdx];
      el.innerHTML = '<b>' + g.text.toUpperCase() + '</b><small>' + g.tip + '</small>' +
        '<div class="bar"><i style="width:0%"></i></div>';
    }
  }
  // the locked tools stay VISIBLE, dimmed. A tool you can see and cannot use
  // yet is a reason to keep playing; a tool that appears from nowhere is a
  // surprise you have to re-read the bar to notice.
  document.querySelectorAll('.tool').forEach(o =>
    o.classList.toggle('locked', !UNLOCKED[o.dataset.tool]));
}

let toastAt = 0;
let goalBarAt = 0;
function stepGoals(dt) {
  // the bar under the goal moves at a few Hz; the goal itself is checked
  // every frame because an unlock has to land the instant it is earned
  goalBarAt += dt;
  if (goalBarAt > 0.25 && goalIdx < GOALS.length) {
    goalBarAt = 0;
    const bar = document.querySelector('#goal .bar i');
    const g = GOALS[goalIdx];
    if (bar && g.progress) bar.style.width =
      Math.round(Math.max(0, Math.min(1, g.progress())) * 100) + '%';
  }
  while (goalIdx < GOALS.length && GOALS[goalIdx].done()) {
    const g = GOALS[goalIdx];
    UNLOCKED[g.unlock] = 1;
    goalIdx++;
    sfxUnlock();
    const t = document.getElementById('toast');
    if (t) { t.textContent = g.got; t.classList.add('on'); toastAt = 3.5; }
    renderGoal();
  }
  if (toastAt > 0) {
    toastAt -= dt;
    if (toastAt <= 0) {
      const t = document.getElementById('toast');
      if (t) t.classList.remove('on');
    }
  }
}

// ── SAVE / LOAD ────────────────────────────────────────────────────────────
// One key per title, so two games exported from the studio do not overwrite
// each other's worlds. Every access is wrapped: storage throws outright in
// some privacy modes, and a game that will not start because it could not read
// a save is worse than a game that forgets.
const SAVE_KEY = 'fs-factory-' +
  String(SPEC.title || 'untitled').toLowerCase().replace(/[^a-z0-9]+/g, '-');
// v2 adds the progression. A v1 save still loads: the goal chain re-derives
// itself from what you have banked on the next frame, so an old world comes
// back with its unlocks intact rather than being refused.
// v3 records which world you are standing in. v1 and v2 still load and default
// to world 0, which is where they were.
const SAVE_V = 3;

function clearFactory() {
  beltsDirty = true;
  eachTile(c => {
    c.rich = 1;                       // a new factory gets fresh ground
    if (c.build) { scene.remove(c.build); c.build = null; }
    c.t = c.mesh ? NODE : EMPTY;
    c.item = 0; c.buf = 0; c.bt = 0; c.fa = 0; c.fb = 0; c.cook = 0; c.rr = 0;
    c.dbt = 0; c.dmin = 0; c.emit = 0; c.left = 0; c.cool = 0;
  });
  items.count = 0;
}

function saveState() {
  const m = [];
  eachTile((c, f, i, j) => {
    if (c.t === EMPTY || c.t === NODE) return;
    m.push([f, i, j, c.t, c.d, c.item | 0, c.buf | 0, c.bt | 0, c.fa | 0,
            c.fb | 0, c.cook | 0, c.rr | 0, c.filt | 0, c.dbt | 0, c.dmin | 0,
            c.emit | 0, Math.round(c.left || 0), Math.round(c.cool || 0)]);
  });
  return {
    v: SAVE_V, n: N, ore, ingots, alloys, cores, runValue,
    up: { tick: UPGRADES.tick.lvl, yield: UPGRADES.yield.lvl,
          smelt: UPGRADES.smelt.lvl },
    price: TRADED.map(t => PRICE[t]),
    p: { face: player.face, pos: player.pos.toArray(),
         fwd: player.fwd.toArray(), pitch: player.pitch },
    g: goalIdx, u: Object.keys(UNLOCKED), vf: [...visitedFaces], w: worldIdx,
    // seams come back from the RNG; how worked each one is does not
    r: (() => { const out = [];
      eachTile((c, f, i, j) => { if (c.mesh && c.rich < 0.999)
        out.push([f, i, j, +c.rich.toFixed(3)]); });
      return out; })(),
    m,
  };
}

function loadState(d) {
  // A SAVE FROM A DIFFERENT WORLD IS NOT A SAVE. The ore seams are generated
  // from a seeded RNG keyed to the grid size; restoring machines onto a
  // different N would put miners on empty ground and leave seams buried under
  // belts, with nothing to indicate why the factory had stopped earning.
  if (!d || !(d.v >= 1 && d.v <= SAVE_V) || d.n !== N) return false;
  clearFactory();
  for (const r of d.m) {
    const [f, i, j, t, dir] = r;
    if (f < 0 || f > 5 || i < 0 || j < 0 || i >= N || j >= N) continue;
    if (!place(f, i, j, t, dir)) continue;
    const c = cells[f][i][j];
    c.item = r[5]; c.buf = r[6]; c.bt = r[7]; c.fa = r[8]; c.fb = r[9];
    c.cook = r[10]; c.rr = r[11]; c.filt = r[12] || CRYSTAL;
    c.dbt = r[13]; c.dmin = r[14]; c.emit = r[15];
    c.left = r[16]; c.cool = r[17];
    const gate = c.build && c.build.getObjectByName('gate');
    if (gate) { gate.material.color.setHex(MIN_COL[c.filt]);
                gate.material.emissive.setHex(MIN_COL[c.filt]); }
  }
  ore = +d.ore || 0; ingots = d.ingots | 0; alloys = d.alloys | 0;
  cores = d.cores | 0; runValue = +d.runValue || 0;
  if (d.up) for (const k in UPGRADES)
    UPGRADES[k].lvl = Math.max(0, Math.min(UPGRADES[k].cap, d.up[k] | 0));
  if (d.price) TRADED.forEach((t, k) => {
    const v = +d.price[k];
    if (isFinite(v)) PRICE[t] = LAST_PRICE[t] =
      Math.max(PRICE_MIN, Math.min(PRICE_MAX, v));
  });
  if (d.p) {
    player.face = d.p.face | 0;
    if (d.p.pos) player.pos.fromArray(d.p.pos);
    if (d.p.fwd) player.fwd.fromArray(d.p.fwd);
    player.pitch = +d.p.pitch || 0;
    faceNormal(player.face, player.up);
    camUp.copy(player.up);
  }
  applyWorld(d.w | 0);
  if (Array.isArray(d.r)) for (const r of d.r) {
    const c = cells[r[0]] && cells[r[0]][r[1]] && cells[r[0]][r[1]][r[2]];
    if (c && c.mesh) c.rich = Math.max(0, Math.min(1, +r[3] || 0));
  }
  goalIdx = Math.max(0, Math.min(GOALS.length, d.g | 0));
  if (Array.isArray(d.u)) for (const k of d.u) UNLOCKED[k] = 1;
  visitedFaces.clear();
  if (Array.isArray(d.vf)) for (const f of d.vf) visitedFaces.add(f | 0);
  visitedFaces.add(player.face);
  applyUpgrades(); renderUpgrades(); renderTicker(); refreshCounts(); renderGoal();
  document.getElementById('tok').textContent = cores;
  return true;
}

function save() {
  try { localStorage.setItem(SAVE_KEY, JSON.stringify(saveState())); return true; }
  catch (e) { return false; }
}
function load() {
  try {
    const raw = localStorage.getItem(SAVE_KEY);
    return raw ? loadState(JSON.parse(raw)) : false;
  } catch (e) { return false; }
}
function wipe() {
  try { localStorage.removeItem(SAVE_KEY); } catch (e) {}
  clearFactory();
  ore = 0; ingots = 0; alloys = 0; cores = 0; runValue = 0;
  for (const k in UPGRADES) UPGRADES[k].lvl = 0;
  goalIdx = 0;
  applyWorld(0);
  for (const k in UNLOCKED) if (!START_TOOLS.includes(k)) delete UNLOCKED[k];
  visitedFaces.clear();
  applyUpgrades(); renderUpgrades(); renderGoal();
  seedLine(true);
  refreshCounts();
  document.getElementById('tok').textContent = cores;
}

// A LINK THAT STARTS A NEW WORLD. Useful to a player who wants to hand someone
// a clean copy, and the only reliable way for a test to get a fresh boot: a
// harness that clears storage from inside the page has it written straight back
// by the beforeunload save that the next navigation fires.
const FRESH = /[?&](fresh|new)=1/.test(location.search);
if (FRESH) { try { localStorage.removeItem(SAVE_KEY); } catch (e) {} }
// the starter line is what a NEW world looks like; a save replaces it whole
const restored = FRESH ? false : load();

let saveClock = 0;
// beforeunload is not reliable on mobile or when a tab is discarded, so the
// periodic write is the real save and this is only the tidy case
addEventListener('beforeunload', save);
addEventListener('visibilitychange', () => { if (document.hidden) save(); });

{
  const h = document.querySelector('#hud h1');
  if (h) h.textContent = (SPEC.title || 'FACTORY').toUpperCase();
  const w = document.getElementById('wipe');
  if (w) w.addEventListener('pointerdown', ev => {
    ev.stopPropagation();
    // a wipe is not undoable, so it asks once — but only once, because a
    // confirm on every click is its own kind of hostile
    if (w.dataset.armed) { wipe(); save(); w.dataset.armed = ''; w.textContent = 'new world'; }
    else { w.dataset.armed = '1'; w.textContent = 'wipe this world?'; }
  });
}
applyUpgrades();
renderUpgrades();
renderTicker();
// after the world exists, so the icons are lit by the same environment it is
buildToolIcons();
renderGoal();
if (!restored) applyWorld(worldIdx);   // a restored save has already chosen
// only a NEW world gets the reveal. A returning player has seen it; showing it
// again on every load is how an intro becomes a thing people hate.
if (!restored && !/[?&]nointro=1/.test(location.search))
  playIntro(WORLDS[worldIdx].name, WORLDS[worldIdx].blurb);

// ── frame ──────────────────────────────────────────────────────────────────
let last = performance.now();
renderer.setAnimationLoop(() => {
  const now = performance.now();
  const dt = Math.min(0.1, (now - last) / 1000);
  last = now;

  stepMarket(dt);
  // seams grow back on their own, and wear their richness as their size
  eachTile(c => {
    if (!c.mesh) return;
    if (c.rich < 1) c.rich = Math.min(1, c.rich + dt * SEAM_REGROW);
    c.mesh.userData.rich = c.rich;
  });
  visitedFaces.add(player.face);
  stepGoals(dt);
  if (!melting) stepRifts(dt);
  saveClock += dt;
  if (saveClock >= 10) { saveClock = 0; save(); }
  if (melting > 0) {
    melting = Math.max(0, melting - dt);
    // the replacement line arrives when the old one has finished falling, not
    // while it is still in the air — otherwise the collapse and the rebuild
    // are the same frame and neither reads
    if (melting === 0) { seedLine(false); refreshCounts(); }
  }
  stepDebris(dt);

  sinceTick += dt;
  rateWindow += dt;
  const before = ore;
  // the tick stops while the factory is still in the air — a meltdown that
  // kept banking value would read as though nothing had been given up
  let ticked = false;
  while (sinceTick >= TICK) { sinceTick -= TICK; if (!melting) { step(); ticked = true; } }
  if (ticked) { paintBeltLoad(); audioFollow(); }
  minedWindow += ore - before;
  if (rateWindow >= 1) {
    // AVERAGE OVER LONGER THAN THE SLOWEST MACHINE (2026-09-06). This sampled
    // a one-second window, and a smelter emits once every three ticks — 1.26s.
    // So the readout sat at 0 for whole seconds while value was visibly
    // climbing, which reads as a broken game rather than as a bursty one. In
    // a genre whose entire hook is watching a number go up, the number has to
    // be trustworthy. Six one-second buckets, reported as their sum.
    rateBuckets.push(minedWindow / rateWindow);
    if (rateBuckets.length > 6) rateBuckets.shift();
    sparkHist.push(minedWindow / rateWindow);
    if (sparkHist.length > 40) sparkHist.shift();
    drawSpark();
    const perSec = rateBuckets.reduce((a, b) => a + b, 0) / rateBuckets.length;
    document.getElementById('rate').textContent = Math.round(perSec * 60);
    minedWindow = 0;
    rateWindow = 0;
  }
  // market prices are fractional, so the banked total is too; nobody wants to
  // read "47.870509893495935" as their score
  document.getElementById('ore').textContent = Math.floor(ore);
  document.getElementById('ingot').textContent = ingots;
  document.getElementById('alloy').textContent = alloys;
  // the buttons light up the moment you can afford them — the whole point of
  // the number climbing is watching it cross a threshold
  if (Math.floor(ore) !== lastOreShown) { lastOreShown = Math.floor(ore); renderUpgrades(); }
  // !! IS LOAD-BEARING (2026-09-08). classList.toggle(name, force) TOGGLES when
  // force is undefined, and UNLOCKED.meltdown is undefined until it is earned —
  // so a locked meltdown button flipped on and off every single frame, which
  // renders as permanently visible and let you prestige before it was unlocked.
  document.getElementById('melt').classList.toggle('on',
    !!(UNLOCKED.meltdown && ore >= MELT_MIN && !melting));
  {
    // the debt and the clock, in words, because a rift you have to remember is
    // a rift you will be surprised by
    let owed = null;
    eachTile(c => { if (c.t === RIFT && c.dbt > 0 && !owed) owed = c; });
    const el = document.getElementById('rift');
    if (el) {
      el.classList.toggle('on', !!owed);
      if (owed) el.innerHTML = '<b>RIFT DEBT</b><small>' + owed.dbt + ' \u00d7 '
        + MINERAL_NAME[owed.dmin] + ' \u00b7 ' + Math.ceil(owed.left) + 's</small>';
    }
  }
  document.getElementById('nitem').textContent = drawItems(sinceTick / TICK);

  if (beltsDirty) rebuildBelts();
  if (!melting) stepEmitters(dt);
  stepWeather(dt);
  stepParticles(dt);
  // the tread scrolls at the speed items actually travel: one tile per tick.
  // A belt whose surface moves at a speed unrelated to its throughput is worse
  // than one that does not move at all.
  if (!melting) TREAD.offset.x -= dt / TICK;
  // A FACTORY WHOSE PARTS DO NOT MOVE IS A DIORAMA. Each machine says what it
  // is doing with the one part that would move if it were real.
  eachTile(c => {
    if (!c.build) return;
    if (c.t === MINER) {
      const bit = c.build.getObjectByName('bit');
      if (bit) bit.rotation.y += dt * 7;
    } else if (c.t === HUB) {
      if (c.pulse > 0) c.pulse = Math.max(0, c.pulse - dt * 2.6);
      const beacon = c.build.getObjectByName('lamp');
      if (beacon) beacon.scale.setScalar(1 + c.pulse * 1.5);
    } else if (c.t === SPLITTER) {
      // slow, and only while it has something to route: a splitter idling at
      // speed reads as broken rather than as busy
      const spin = c.build.getObjectByName('spin');
      if (spin) spin.rotation.y += dt * (c.item ? 2.2 : 0.35);
    } else if (c.t === FORGE) {
      const halo = c.build.getObjectByName('halo');
      if (halo) {
        halo.visible = c.cook > 0;
        halo.rotation.z += dt * 3.4;
        halo.scale.setScalar(1 + Math.sin(performance.now() * 0.006) * 0.06);
      }
    } else if (c.t === FILTER) {
      const gate = c.build.getObjectByName('gate');
      if (gate) gate.material.emissiveIntensity =
        0.45 + Math.sin(performance.now() * 0.003) * 0.18;
    }
  });

  // a crystal on the west face spins about the west face's up, and one being
  // mined flexes as each crystal is pulled out of it
  scene.traverse(o => {
    if (!o.userData.spin) return;
    const ax = o.userData.axis;
    if (ax) o.rotateOnAxis(_bx.set(0, 1, 0), dt * o.userData.spin);
    else o.rotation.y += dt * o.userData.spin;
    // size = richness, plus the extraction flex on top of it. A worked-out
    // seam is a small one, which is a thing you can see from orbit.
    if (o.userData.rich !== undefined || o.userData.pulse > 0) {
      const rich = o.userData.rich === undefined ? 1 : o.userData.rich;
      const b = (o.userData.base || 1) * (0.42 + 0.58 * rich);
      if (o.userData.pulse > 0) {
        o.userData.pulse = Math.max(0, o.userData.pulse - dt * 3.2);
        o.scale.setScalar(b * (1 + Math.sin(o.userData.pulse * Math.PI) * 0.22));
      } else {
        o.scale.setScalar(b);
      }
    }
  });

  if (intro > 0) {
    // the reveal: three-quarters of a turn, easing in from far out, and a
    // gentle drop in pitch so the last frame is nearly the player's own view
    intro = Math.max(0, intro - dt);
    const t = 1 - intro / introTotal;                    // 0 -> 1
    const e = t * t * (3 - 2 * t);
    // Two different shots. The arrival eases IN from far out, low, a
    // three-quarter turn. The meltdown starts high and close over the face the
    // factory is on — so the machines going up fill the frame — and pulls OUT
    // until the whole world is in view as the debris lands. The first version
    // ran the arrival path backwards, which began at a wide of the cube with
    // the debris three pixels tall at the top edge.
    let yaw, pitch, dist;
    if (introFrom.reverse) {
      const n = FACES[player.face].n;
      // the orbit rig only looks at the origin, so aim at the FACE by choosing
      // yaw and pitch from its normal, then rise and pull away along it
      const fy = Math.atan2(n[0], n[2]);
      const fp = Math.asin(Math.max(-0.99, Math.min(0.99, n[1])));
      yaw = fy + (e - 0.5) * 0.5;
      pitch = fp * (1 - e * 0.32);
      dist = HALF * (1.9 + e * 2.6);
    } else {
      yaw = introFrom.yaw + e * Math.PI * 1.5;
      pitch = 1.05 - e * 0.55;
      dist = HALF * (5.2 - e * 2.6);
    }
    camera.position.set(Math.sin(yaw) * Math.cos(pitch) * dist,
                        Math.sin(pitch) * dist,
                        Math.cos(yaw) * Math.cos(pitch) * dist);
    camera.lookAt(0, 0, 0);
    scene.fog = null;
    ghost.visible = false;
    heldRig.visible = false;
    if (intro === 0) endIntro();
  } else if (overhead || inspectOn) {
    camera.position.set(
      Math.sin(orbYaw) * Math.cos(orbPitch) * orbDist,
      Math.sin(orbPitch) * orbDist,
      Math.cos(orbYaw) * Math.cos(orbPitch) * orbDist);
    camera.lookAt(0, 0, 0);
    // fog is tuned for standing ON the surface; from an orbit it erases the
    // whole worldlet, which is the one view that has to read at a glance
    scene.fog = null;
    ghost.visible = false;
    heldRig.visible = false;      // nobody is holding it from up here
  } else {
    if (!scene.fog) scene.fog = worldFog;
    movePlayer(dt);
    camera.position.copy(player.pos);

    // Built from a basis, not from Euler angles: there is no global "up" left
    // to write a yaw against once the player can be standing on the underside
    // of the world. camUp trails the true up so an edge crossing rolls.
    camUp.lerp(player.up, Math.min(1, dt * 7)).normalize();
    _bz.copy(player.fwd).addScaledVector(camUp, -player.fwd.dot(camUp));
    if (_bz.lengthSq() < 1e-8) _bz.copy(player.fwd);
    _bz.normalize();
    _bx.crossVectors(_bz, camUp).normalize();     // right
    _by.crossVectors(_bx, _bz).normalize();       // orthonormal up
    _mx.makeBasis(_bx, _by, _bz.negate());        // a camera looks down -Z
    camera.quaternion.setFromRotationMatrix(_mx);
    camera.rotateX(player.pitch);
    // A CAMERA THAT DOES NOT MOVE WHEN YOU WALK reads as a drone, not a person.
    // After the basis, so it can use the camera's OWN right vector — _rt is a
    // scratch the edge-crossing loop overwrites with a face axis, and swaying
    // along whatever that happened to be is not a bob.
    bobPhase += dt * (moveMag > 0.01 ? 9.5 : 0) * (keys['ShiftLeft'] ? 1.35 : 1);
    bobAmt += ((moveMag > 0.01 && player.onGround ? 1 : 0) - bobAmt) *
              Math.min(1, dt * 7);
    camera.position.addScaledVector(_by, Math.sin(bobPhase * 2) * 0.045 * bobAmt);
    camera.position.addScaledVector(_bx, Math.sin(bobPhase) * 0.035 * bobAmt);
    // the rig rides the camera, so it only needs a little sway of its own —
    // a held object that is perfectly rigid to the view reads as painted on
    heldRig.visible = true;
    heldRig.position.set(0.36 + Math.sin(bobPhase) * 0.012 * bobAmt,
                         -0.25 + Math.sin(bobPhase * 2) * 0.009 * bobAmt,
                         -0.55);
    heldRig.rotation.z = 0.06 + Math.sin(bobPhase) * 0.02 * bobAmt;
    holo.rotation.y += dt * 0.9;
    holo.position.y = 0.26 + Math.sin(performance.now() * 0.0022) * 0.008;
    updateGhost();
  }
  document.body.classList.toggle('overhead', overhead);
  renderFrame();
});

// ── WHAT YOU ARE HOLDING ───────────────────────────────────────────────────
// A projector on your forearm, and above it a hologram of whatever the tool
// bar has selected. Parented to the camera, so it inherits the walk bob for
// free and only needs a little lag of its own.
const heldRig = new THREE.Group();
{
  const dark = new THREE.MeshStandardMaterial({ color: 0x2a3350, roughness: 0.5,
    metalness: 0.65, vertexColors: true, envMapIntensity: 0.8 });
  addRim(dark, 0x8fd8ff, 2.4, 0.5);
  const body = new THREE.Mesh(mergeParts([
    { g: _box(0.13, 0.10, 0.34), z: 0.10 },                    // forearm
    { g: _box(0.16, 0.13, 0.16), z: -0.10, tint: 0.85 },       // wrist unit
    { g: _cyl(0.018, 0.018, 0.10, 6), x: 0.055, y: 0.075, z: -0.14, tint: 1.2 },
    { g: _cyl(0.018, 0.018, 0.10, 6), x: -0.055, y: 0.075, z: -0.14, tint: 1.2 },
    { g: _cyl(0.018, 0.018, 0.10, 6), y: 0.075, z: -0.19, tint: 1.2 },
  ], { floor: 0.55, reach: 0.25 }), dark);
  heldRig.add(body);

  // the emitter's own glow, so the projection has a source
  const emit3 = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.03, 0.02, 10),
    new THREE.MeshBasicMaterial({ color: ACCENT, transparent: true, opacity: 0.85 }));
  emit3.position.set(0, 0.115, -0.155);
  heldRig.add(emit3);

  // SMALL, AND IN THE CORNER. The first pass sat a forearm the size of a
  // smelter in the middle-right of the view; a held thing should be present
  // at the edge of attention, not competing with the factory for it.
  heldRig.scale.setScalar(0.62);
  heldRig.position.set(0.36, -0.25, -0.55);
  heldRig.rotation.set(-0.12, 0.34, 0.06);
  heldRig.renderOrder = 2;
  camera.add(heldRig);
  scene.add(camera);          // a camera only renders children once it is IN the scene
}

// The hologram. Normalised by each geometry's own radius so a rift and a belt
// read at the same size — a preview that changes scale with the machine tells
// you about the mesh, not about the choice.
const holoMat = new THREE.MeshBasicMaterial({ color: ACCENT, transparent: true,
  opacity: 0.55, depthWrite: false, blending: THREE.AdditiveBlending });
const holo = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), holoMat);
holo.position.set(0, 0.26, -0.16);
holo.renderOrder = 3;
heldRig.add(holo);

const HOLO_GEO = {
  miner: 'miner', belt: 'beltFrame', smelter: 'smelt', splitter: 'split',
  hub: 'hub', forge: 'forge', filter: 'filter', rift: 'riftBase',
};
function setHolo(name) {
  const g = GEO[HOLO_GEO[name]];
  if (!g) { holo.visible = false; return; }
  holo.visible = true;
  holo.geometry = g;
  g.computeBoundingSphere();
  const r = Math.max(0.001, g.boundingSphere.radius);
  holo.scale.setScalar(0.09 / r);
  holoMat.color.setHex(name === 'erase' ? 0xff6b7d : ACCENT);
}
setHolo(tool);      // here, AFTER HOLO_GEO exists — not up by the tool bar

// ── SOUND ──────────────────────────────────────────────────────────────────

function noiseBuffer(ctx, seconds) {
  const n = Math.floor(ctx.sampleRate * seconds);
  const buf = ctx.createBuffer(1, n, ctx.sampleRate);
  const d = buf.getChannelData(0);
  let last = 0;
  for (let k = 0; k < n; k++) {
    // brown-ish rather than white: a conveyor is a low rumble, not a hiss
    last = (last + (Math.random() * 2 - 1) * 0.04) / 1.04;
    d[k] = last * 3.2;
  }
  return buf;
}

function audioStart() {
  if (AUDIO.ready) return;
  const AC = window.AudioContext || window.webkitAudioContext;
  if (!AC) return;
  const ctx = new AC();
  const master = ctx.createGain();
  master.gain.value = AUDIO.muted ? 0 : 0.7;
  master.connect(ctx.destination);

  // the hum: two detuned lows, lowpassed, barely there
  const humGain = ctx.createGain(); humGain.gain.value = 0.045;
  const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 220;
  for (const f of [54, 54.7]) {
    const o = ctx.createOscillator(); o.type = 'sawtooth'; o.frequency.value = f;
    o.connect(lp); o.start();
  }
  lp.connect(humGain); humGain.connect(master);

  // the belts: brown noise, level follows the belt count
  const bGain = ctx.createGain(); bGain.gain.value = 0;
  const bSrc = ctx.createBufferSource(); bSrc.buffer = noiseBuffer(ctx, 2.5);
  bSrc.loop = true;
  const bp = ctx.createBiquadFilter(); bp.type = 'bandpass';
  bp.frequency.value = 340; bp.Q.value = 0.7;
  bSrc.connect(bp); bp.connect(bGain); bGain.connect(master); bSrc.start();

  // the furnace: a low rumble that opens while something cooks
  const fGain = ctx.createGain(); fGain.gain.value = 0;
  const fSrc = ctx.createBufferSource(); fSrc.buffer = noiseBuffer(ctx, 3.1);
  fSrc.loop = true;
  const flp = ctx.createBiquadFilter(); flp.type = 'lowpass'; flp.frequency.value = 120;
  fSrc.connect(flp); flp.connect(fGain); fGain.connect(master); fSrc.start();

  Object.assign(AUDIO, { ctx, master, hum: humGain, belts: bGain, furnace: fGain,
                         ready: true });
}

// a short tone with an envelope; everything transient is built on this
function tone(freq, dur, type, vol, when) {
  if (!AUDIO.ready || AUDIO.muted) return;
  const ctx = AUDIO.ctx, t0 = ctx.currentTime + (when || 0);
  const o = ctx.createOscillator(), g = ctx.createGain();
  o.type = type || 'sine'; o.frequency.value = freq;
  g.gain.setValueAtTime(0, t0);
  g.gain.linearRampToValueAtTime(vol || 0.2, t0 + 0.008);
  g.gain.exponentialRampToValueAtTime(0.0008, t0 + dur);
  o.connect(g); g.connect(AUDIO.master);
  o.start(t0); o.stop(t0 + dur + 0.02);
}

const SOLD_PITCH = { 1: 660, 2: 587, 3: 740, 4: 880, 5: 784, 6: 988, 7: 1175 };
function sfxSold(type) { tone(SOLD_PITCH[type] || 660, 0.16, 'sine', 0.16); }
function sfxUnlock() { tone(523, 0.22, 'triangle', 0.18); tone(784, 0.36, 'triangle', 0.18, 0.13); }
function sfxMelt() {
  if (!AUDIO.ready || AUDIO.muted) return;
  const ctx = AUDIO.ctx, t0 = ctx.currentTime;
  const o = ctx.createOscillator(), g = ctx.createGain();
  o.type = 'sawtooth';
  o.frequency.setValueAtTime(420, t0);
  o.frequency.exponentialRampToValueAtTime(48, t0 + 2.2);
  g.gain.setValueAtTime(0.22, t0);
  g.gain.exponentialRampToValueAtTime(0.001, t0 + 2.3);
  o.connect(g); g.connect(AUDIO.master); o.start(t0); o.stop(t0 + 2.4);
}
function sfxPlace() { tone(330, 0.07, 'square', 0.06); }

function audioMute(on) {
  AUDIO.muted = on;
  if (AUDIO.master) AUDIO.master.gain.value = on ? 0 : 0.7;
  try { localStorage.setItem('fs-factory-muted', on ? '1' : '0'); } catch (e) {}
}

// the continuous layers follow the factory, once a tick is plenty
function audioFollow() {
  if (!AUDIO.ready) return;
  let belts = 0, cooking = 0;
  eachTile(c => { if (c.t === BELT) belts++;
                  if ((c.t === SMELTER || c.t === FORGE) && c.cook > 0) cooking++; });
  const t = AUDIO.ctx.currentTime;
  AUDIO.belts.gain.setTargetAtTime(Math.min(0.11, belts * 0.004), t, 0.4);
  AUDIO.furnace.gain.setTargetAtTime(Math.min(0.18, cooking * 0.06), t, 0.5);
}

// ── THE REVEAL ─────────────────────────────────────────────────────────────
// A slow orbit of the whole worldlet with its name over it, then the camera
// drops to the player. Runs from a single clock so it cannot desynchronise
// from the HUD fade; ends early on any input.
function playIntro(name, blurb, secs, reverse) {
  const card = document.getElementById('title');
  if (card) {
    card.querySelector('b').textContent = String(name).toUpperCase();
    card.querySelector('small').textContent = blurb || '';
    card.classList.add('on');
  }
  introTotal = secs || 3.6;
  intro = introTotal;
  // reverse pulls BACK — near to far — which is the meltdown's shape: the
  // machines fill the frame, then the whole world is in view as they land
  introFrom = { yaw: orbYaw, pitch: orbPitch, dist: orbDist, reverse: !!reverse };
  if (document.pointerLockElement === renderer.domElement) document.exitPointerLock();
}
function endIntro() {
  // NO EARLY RETURN ON intro. The clock reaches zero one line before this is
  // called from the frame loop, so a guard on `intro` returned before taking
  // the card down and the title sat over play forever. Removing a class that
  // is already gone costs nothing; leaving one up costs the whole first
  // impression.
  intro = 0;
  const card = document.getElementById('title');
  if (card) card.classList.remove('on');
}
addEventListener('keydown', endIntro);
addEventListener('pointerdown', endIntro);

// ── STUDIO INSPECTOR BRIDGE ────────────────────────────────────────────────
// Standalone (itch.io, the flagship demo, a shared zip) this is inert: nothing
// is listening and window.parent is the window itself. Inside the studio it is
// how Inspect, drag-to-place and the property panel reach the running game.
let inspectOn = false;
let overheadBefore = false;
let lastPick = null;                     // the tile the studio last asked about

function setInspectOn(on) {
  if (on === inspectOn) return;
  inspectOn = on;
  if (on) {
    overheadBefore = overhead;
    overhead = true;                     // inspecting is a camera you can aim
    if (document.pointerLockElement === renderer.domElement) document.exitPointerLock();
  } else {
    overhead = overheadBefore;
  }
  document.body.classList.toggle('inspect', on);
}

{
  const rc = new THREE.Raycaster();
  const nv = new THREE.Vector2();
  const send = m => { try { window.parent.postMessage(m, '*'); } catch (e) {} };

  function pickAt(cx, cy, kindEv) {
    nv.set((cx / innerWidth) * 2 - 1, -(cy / innerHeight) * 2 + 1);
    rc.setFromCamera(nv, camera);
    for (const h of rc.intersectObjects(scene.children, true)) {
      if (h.object.isLine || h.object === ghost || ghost.children.indexOf(h.object) >= 0)
        continue;                        // grid lines and the build ghost are not things
      let o = h.object, tag = null;
      // an instanced belt has no object of its own, so the instance id is the
      // only way back to the tile it came from
      const bk = beltFrames.indexOf(h.object) >= 0 ? beltFrames.indexOf(h.object)
               : beltDecks.indexOf(h.object);
      if (bk >= 0 && h.instanceId != null && beltIndex[bk][h.instanceId]) {
        const t2 = beltIndex[bk][h.instanceId];
        tag = { type: 'machine', name: 'belt',
                detail: FACES[t2.face].name + ' face · tile ' + t2.i + ',' + t2.j,
                face: t2.face, i: t2.i, j: t2.j };
      }
      while (!tag && o) { if (o.userData && o.userData.fsTag) { tag = o.userData.fsTag; break; }
                          o = o.parent; }
      const t = tag && tag.face !== undefined
        ? { face: tag.face, i: tag.i, j: tag.j } : tileOfPoint(h.point);
      lastPick = t;
      send({ type: 'fs-pick', kind: kindEv,
             x: +h.point.x.toFixed(2), y: +h.point.y.toFixed(2), z: +h.point.z.toFixed(2),
             tile: t,
             target: tag || (t
               ? { type: 'ground', name: FACES[t.face].name + ' face',
                   detail: 'tile ' + t.i + ',' + t.j + ' · '
                           + MINERAL_NAME[MINERAL_OF_FACE[t.face]] + ' country' }
               : { type: 'ground', name: 'ground', detail: 'off the worldlet' }) });
      return true;
    }
    // A DROP ALWAYS LANDS, or says why it did not. Aimed past the cube there is
    // no ground plane to fall back on — a worldlet is surrounded by space — so
    // the honest answer is dropfail rather than a silent nothing, which the
    // studio would sit and wait on forever.
    if (kindEv === 'drop') send({ type: 'fs-pick', kind: 'dropfail' });
    return false;
  }

  // A SPAWN NEEDS A FACE, AND x/z CANNOT CARRY ONE. The studio sends the world
  // coordinates its own drop reported, which on a flat map is enough and on a
  // cube is not: (x,z) names a column through the world, not a tile. So a spawn
  // lands on the tile the pick that preceded it resolved.
  const SPAWN_KIND = {
    miner: MINER, drill: MINER, mine: MINER,
    belt: BELT, conveyor: BELT, conveyer: BELT,
    smelter: SMELTER, furnace: SMELTER, kiln: SMELTER,
    splitter: SPLITTER, split: SPLITTER,
    hub: HUB, depot: HUB, base: HUB,
    forge: FORGE, alloy: FORGE,
    filter: FILTER, sorter: FILTER,
    rift: RIFT, chronos: RIFT, portal: RIFT,
  };

  addEventListener('message', e => {
    const d = e.data;
    if (!d || !d.type) return;
    if (d.type === 'fs-inspect') { setInspectOn(!!d.on); return; }
    if (d.type === 'fs-dropat') { pickAt(d.cx, d.cy, 'drop'); return; }
    if (d.type === 'fs-spawn') {
      const kind = String(d.kind || '').toLowerCase().replace(/[^a-z]/g, '');
      const type = SPAWN_KIND[kind];
      if (!type) {
        send({ type: 'fs-spawned', ok: false, kind: d.kind,
               err: 'a factory builds machines — try miner, belt, smelter, '
                    + 'splitter, hub, forge or filter' });
        return;
      }
      const t = (d.tile && d.tile.face !== undefined) ? d.tile : lastPick;
      if (!t) { send({ type: 'fs-spawned', ok: false, kind: d.kind,
                       err: 'nothing picked yet — click a tile first' }); return; }
      const ok = place(t.face, t.i, t.j, type, 0) !== false;
      send({ type: 'fs-spawned', ok, kind: d.kind,
             err: ok ? undefined : 'a miner only goes on an ore seam' });
      return;
    }
  });

  // hover picks, so the studio's panel updates as you move over the world.
  // Throttled: an unthrottled raycast per mousemove is a scene traversal per
  // pixel of travel, and this runs beside a simulation.
  let hoverAt = 0;
  renderer.domElement.addEventListener('mousemove', e => {
    if (!inspectOn) return;
    const now = performance.now();
    if (now - hoverAt < 90) return;
    hoverAt = now;
    pickAt(e.clientX, e.clientY, 'hover');
  });
  renderer.domElement.addEventListener('click', e => {
    if (inspectOn) pickAt(e.clientX, e.clientY, 'click');
  });
  window.__pickAt = pickAt;
}

// ORBIT BY DRAGGING. The overhead camera could only be zoomed, which is fine
// as a glance at your own factory and useless as an inspector: half the world
// is on faces you cannot bring into view.
{
  let drag = null;
  renderer.domElement.addEventListener('pointerdown', e => {
    if (!overhead && !inspectOn) return;
    // Right-drag orbits, because in the overhead view LEFT-drag already draws
    // belts and taking that away to spin the camera would be a worse trade.
    // While inspecting there is no drawing, so left-drag orbits too.
    if (e.button !== 2 && !(inspectOn && e.button === 0)) return;
    drag = { x: e.clientX, y: e.clientY };
  });
  addEventListener('pointermove', e => {
    if (!drag) return;
    orbYaw -= (e.clientX - drag.x) * 0.006;
    orbPitch = Math.max(-1.45, Math.min(1.45, orbPitch + (e.clientY - drag.y) * 0.005));
    drag.x = e.clientX; drag.y = e.clientY;
  });
  addEventListener('pointerup', () => { drag = null; });
}

// The shot gate, the scene audit and the brief check all talk to window.__game.
// A second genre that invented its own interface would need a second gate, and
// then only one of them would stay honest.
window.__game = {
  ready: true,
  pos: () => player.pos.toArray(),
  keys: {},
  pick: (cx, cy) => window.__pickAt(cx, cy, 'click'),
  inspect: on => setInspectOn(on),
  get inspecting() { return inspectOn; },
  stats: () => ({ calls: sceneCalls,
                  tris: sceneTris,
                  post: POST.on,
                  programs: renderer.info.programs ? renderer.info.programs.length : -1,
                  textures: renderer.info.memory.textures,
                  geometries: renderer.info.memory.geometries }),
  facts: () => ({
    genre: 'factory',
    style: SPEC.style || 'default',
    grid: N,
    nodes: NODE_COUNT,
    value: ore,
    ingots,
    machines: (() => { let n = 0;
      eachTile(c => { if (c.t !== EMPTY && c.t !== NODE) n++; });
      return n; })(),
    items_on_belts: items.count,
    particles: (() => { let n = 0; for (let k = 0; k < PMAX; k++) if (pLife[k] > 0) n++;
                        return n; })(),
    alloys,
    prices: TRADED.map(t => +PRICE[t].toFixed(3)),
    restored,
    intro: +intro.toFixed(2),
    audio: { ready: AUDIO.ready, muted: AUDIO.muted,
             state: AUDIO.ctx ? AUDIO.ctx.state : null },
    world: WORLDS[worldIdx].id,
    world_name: WORLDS[worldIdx].name,
    worlds_open: WORLDS.filter(w => cores >= w.cores).length,
    goal: goalIdx < GOALS.length ? GOALS[goalIdx].text : null,
    goal_index: goalIdx,
    unlocked: Object.keys(UNLOCKED),
    faces_visited: visitedFaces.size,
    weather: (WORLDS[worldIdx].weather || null) && {
      rate: WORLDS[worldIdx].weather.rate, fall: WORLDS[worldIdx].weather.fall },
    seams: (() => { let n = 0, sum = 0, worked = 0;
      eachTile(c => { if (c.mesh) { n++; sum += c.rich; if (c.rich < 0.9) worked++; } });
      return { count: n, mean_rich: n ? +(sum / n).toFixed(3) : 1, worked }; })(),
    rift: (() => { let r = null;
      eachTile(c => { if (c.t === RIFT && !r) r = { debt: c.dbt,
        ore: MINERAL_NAME[c.dmin] || null, left: +c.left.toFixed(1),
        cool: +c.cool.toFixed(1), emit: c.emit }; });
      return r; })(),
    best: TRADE_NAME[TRADED.reduce((a, b) => PRICE[a] > PRICE[b] ? a : b)],
    minerals: MINERAL_OF_FACE.map(m => MINERAL_NAME[m]),
    cores,
    run_value: +runValue.toFixed(1),
    melting: +melting.toFixed(2),
    debris: debris.length,
    faces: 6,
    player_face: FACES[player.face].name,
    player_up: player.up.toArray().map(v => +v.toFixed(2)),
    player_y: +player.pos.y.toFixed(2),
  }),
};
window.__scene = scene;
window.__renderer = renderer;
window.__camera = camera;

window.__factory = {
  cells, items, N, T, player, HALF, FACES,
  stepTile, tileWorld, faceOfPoint,
  TYPES: { EMPTY, MINER, BELT, HUB, NODE, SMELTER, SPLITTER, FORGE, FILTER,
           RIFT, CRYSTAL, EMBER, SALT, INGOT, INGOT_E, INGOT_S, ALLOY },
  MINERAL_OF_FACE, get alloys() { return alloys; }, cycleFilter,
  riftOpen, riftStorm, RIFT_COUNT, RIFT_WINDOW,
  save, load, wipe, saveState, SAVE_KEY, TREAD, beltFrames, beltDecks, POST,
  beltShape, scatterVent, scatterBolt, scatterSpots, renderThumb, GEO, MAT,
  SEAM_COST, SEAM_REGROW, SEAM_FLOOR,
  step,                 // one simulation tick, for a harness that cannot wait
  playIntro, endIntro,
  audioStart, audioMute, sfxSold, sfxUnlock, sfxMelt, AUDIO,
  beltIndexOf: (f, i, j) => {
    const k = beltShape(f, i, j, cells[f][i][j]);
    return beltIndex[k].findIndex(t => t.face === f && t.i === i && t.j === j);
  },
  GOALS, UNLOCKED, get goalIdx() { return goalIdx; }, visitedFaces,
  WORLDS, travelTo, applyWorld, get worldIdx() { return worldIdx; },
  // aim the overhead camera, so a harness can look at a chosen face
  orbit: (yaw, pitch, dist) => { orbYaw = yaw; orbPitch = pitch;
                                 if (dist) orbDist = dist; },
  addCores: n => { cores += n; document.getElementById('tok').textContent = cores;
                   renderWorlds(); },
  PRICE, TRADED, stepMarket,
  UPGRADES, buy, costOf, get tick() { return TICK; },
  meltdown, MELT_MIN, get cores() { return cores; },
  addValue: n => { ore += n; },
  get ingots() { return ingots; },
  get ore() { return ore; },
  place, removeAt,
  camPos: () => camera.position.toArray(),
  ghostVisible: () => ghost.visible,
};
